                                {inputModes[index] === 'total' ? 'Auto-Calc Unit' : 'Enter Total'}
                            </button>
                        </div>
                        <div className="relative group">
                            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-medium z-10">₹</span>
