            >
                <Filter size={16} /> Filters
            </button>
            {showFilters && (
                <GlassCard className="mt-2 p-4 animate-in slide-in-from-top-2">
                    <div className="space-y-3">
                        <div className="relative">
                            <SearchIcon size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                            <input 
                                className="w-full bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-xl pl-9 pr-3 py-2 text-sm outline-none"
                                placeholder="Filter by product name..."
                                value={filters.productName}
                                onChange={e => setFilters({...filters, productName: e.target.value})}
                            />
                        </div>
                        <div className="grid grid-cols-3 gap-3">
                            <input 
                                type="date"
                                className="bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-xl px-3 py-2 text-sm outline-none"
                                value={filters.date}
                                onChange={e => setFilters({...filters, date: e.target.value})}
                            />
                            <input 
                                type="number"
                                placeholder="Min Qty"
                                className="bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-xl px-3 py-2 text-sm outline-none"
                                value={filters.minQty}
                                onChange={e => setFilters({...filters, minQty: e.target.value})}
                            />
                             <input 
                                type="number"
                                placeholder="Min Price"
                                className="bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-xl px-3 py-2 text-sm outline-none"
                                value={filters.minPrice}
                                onChange={e => setFilters({...filters, minPrice: e.target.value})}
                            />
                        </div>
                        <div className="flex justify-end pt-2">
                            <button 
                                onClick={() => setFilters({ productName: '', date: '', minQty: '', minPrice: '' })}
                                className="text-xs text-red-500 font-bold hover:underline"
                            >
                                Clear All
                            </button>
                        </div>
                    </div>
                </GlassCard>
            )}
          </div>

          {[...filteredSales].map((report, i) => (
             <GlassCard 
                key={report.date} 
                className="p-4 animate-in slide-in-from-bottom-4 duration-500" 
                onClick={() => setSelectedDateReport(report)}
                // Stagger List animation slightly
                style={{ animationDelay: `${i * 0.05}s` }}
             >
                <div className="flex justify-between items-center">
                    <div>
                        <p className="font-bold flex items-center gap-2">
                            {new Date(report.date).toLocaleDateString()}
                            {report.isWeekOff && <span className="text-[10px] bg-gray-200 text-gray-600 px-2 py-0.5 rounded-full">OFF</span>}
                        </p>
                        <p className="text-sm text-slate-500">
                            {report.isWeekOff ? 'Week Off' : `${report.totalQty} items • ₹${report.totalValue.toLocaleString()}`}
                        </p>
                    </div>
                    <div className="h-8 w-8 bg-zinc-100 dark:bg-zinc-800 rounded-full flex items-center justify-center text-black dark:text-white">
                        <List size={16} />
                    </div>
                </div>
             </GlassCard>
          ))}
          {filteredSales.length === 0 && (
             <div className="text-center py-10 opacity-60">
                <Filter size={32} className="mx-auto mb-2 text-slate-400" />
                <p className="text-slate-500 text-sm">No matching records found.</p>
             </div>
          )}
        </div>
      )}

      {/* Details Modal */}
      <Modal 
        isOpen={!!selectedDateReport} 
        onClose={() => { setSelectedDateReport(null); cancelEdit(); }}
        title={selectedDateReport ? new Date(selectedDateReport.date).toDateString() : ''}
      >
        {selectedDateReport && (
          <div className="space-y-6 pb-4">
            {selectedDateReport.isWeekOff ? (
                <div className="text-center py-8 bg-gray-50 dark:bg-white/5 rounded-2xl border border-dashed border-gray-300">
                    <Ban size={40} className="mx-auto text-gray-400 mb-2" />
                    <p className="text-gray-500 font-medium">Marked as Week Off</p>
                </div>
            ) : (
                <>
                {/* Stats */}
                <div className="grid grid-cols-2 gap-4">
                    <div className="bg-blue-50 dark:bg-blue-900/30 p-3 rounded-lg text-center">
                        <p className="text-xs text-slate-500">Value</p>
                        <p className="font-bold text-blue-600">₹{selectedDateReport.totalValue.toLocaleString()}</p>
                    </div>
                    <div className="bg-purple-50 dark:bg-purple-900/30 p-3 rounded-lg text-center">
                        <p className="text-xs text-slate-500">Quantity</p>
                        <p className="font-bold text-purple-600">{selectedDateReport.totalQty}</p>
                    </div>
                </div>

                {/* Items List */}
                <div className="space-y-3">
                    <h4 className="text-sm font-semibold text-slate-500 uppercase tracking-wider sticky top-0 bg-white/95 dark:bg-black/95 backdrop-blur py-2 z-10">Items Sold</h4>
                    {selectedDateReport.items.map((item, idx) => {
                        const isEditing = editingItemIndex === idx;

                        return (
                        <div key={idx} className={`flex justify-between items-center p-3 rounded-lg border transition-all ${isEditing ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-200' : 'bg-white/40 dark:bg-white/5 border-white/10'}`}>
                            {isEditing && editItemState ? (
                                <div className="w-full space-y-2">
                                    <input 
                                        className="w-full bg-transparent border-b border-blue-300 text-sm font-medium focus:outline-none"
                                        value={editItemState.productName}
                                        onChange={(e) => setEditItemState({...editItemState, productName: e.target.value})}
                                        placeholder="Product Name"
                                    />
                                    <div className="flex gap-2">
                                        <div className="flex-1">
                                            <label className="text-[9px] uppercase text-slate-500 font-bold">Qty</label>
                                            <input 
                                                type="number" 
                                                className="w-full bg-transparent border-b border-blue-300 text-sm focus:outline-none"
                                                value={editItemState.quantity}
                                                onChange={(e) => setEditItemState({...editItemState, quantity: parseInt(e.target.value) || 0})}
                                            />
                                        </div>
                                        <div className="flex-1">
                                            <label className="text-[9px] uppercase text-slate-500 font-bold">Unit Price</label>
                                            <input 
                                                type="number" 
                                                className="w-full bg-transparent border-b border-blue-300 text-sm focus:outline-none"
                                                value={editItemState.price}
                                                onChange={(e) => setEditItemState({...editItemState, price: parseFloat(e.target.value) || 0})}
                                            />
                                        </div>
                                    </div>
                                    <div className="flex justify-end gap-2 mt-2">
                                        <button onClick={cancelEdit} className="p-1 rounded-full bg-gray-200 text-gray-600"><X size={14} /></button>
                                        <button onClick={() => saveEditItem(selectedDateReport, idx)} className="p-1 rounded-full bg-green-500 text-white"><Check size={14} /></button>
                                    </div>
                                </div>
                            ) : (
                                <>
                                <div>
                                    <p className="font-medium text-sm">{item.productName}</p>
                                    <p className="text-xs text-slate-500">₹{item.price} x {item.quantity}</p>
                                </div>
                                <div className="flex items-center gap-2">
                                    <p className="font-bold text-sm mr-2">₹{item.price * item.quantity}</p>
                                    <button onClick={() => startEditItem(item, idx)} className="text-blue-400 hover:text-blue-600 p-1">
                                        <Pencil size={14} />
                                    </button>
                                    <button onClick={() => handleRemoveItem(selectedDateReport, idx)} className="text-red-400 hover:text-red-600 p-1">
                                        <Trash2 size={14} />
                                    </button>
                                </div>
                                </>
                            )}
                        </div>
                    )})}
                </div>

                {/* Bill Images */}
                {getReportImages(selectedDateReport).length > 0 && (
                    <div className="mt-4">
                        <h4 className="text-sm font-semibold text-slate-500 mb-2 sticky top-0 bg-white/95 dark:bg-black/95 backdrop-blur py-2 z-10">Bill Copies ({getReportImages(selectedDateReport).length})</h4>
                        <div className="grid grid-cols-2 gap-3">
                            {getReportImages(selectedDateReport).map((img, idx) => (
                                <div key={idx} className="relative group rounded-xl overflow-hidden border border-white/20 aspect-square">
                                    <img 
                                        src={img} 
                                        alt="Bill" 
                                        className="w-full h-full object-cover"
                                    />
                                    <div className="absolute inset-0 bg-black/40 flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity gap-2">
                                        <div className="flex gap-2">
                                            <button onClick={() => setZoomedImage(img)} className="p-2 bg-white rounded-full text-black hover:bg-gray-100">
                                                <Maximize2 size={16} />
                                            </button>
                                            <button onClick={() => downloadImage(img, selectedDateReport.date, idx)} className="p-2 bg-white rounded-full text-black hover:bg-gray-100">
                                                <Download size={16} />
                                            </button>
                                        </div>
                                        <button onClick={() => handleRemoveImage(selectedDateReport, idx)} className="px-3 py-1 bg-red-500 text-white text-xs rounded-full hover:bg-red-600 mt-2">
                                            Delete
                                        </button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
                </>
            )}

             {/* Actions */}
             <div className="grid grid-cols-2 gap-3 mt-6 sticky bottom-0 bg-white/0 pt-2">
                <GlassButton onClick={() => copyReport(selectedDateReport)} variant="primary">
                    Copy Report
                </GlassButton>
                <GlassButton variant="danger" onClick={() => handleDeleteEntry(selectedDateReport.date)}>
                    Delete All
                </GlassButton>
             </div>
          </div>
        )}
      </Modal>

      {/* AI Coach Chat Modal */}
      <Modal 
        isOpen={showCoach} 
        onClose={() => setShowCoach(false)} 
        title="Sales Coach"
      >
        <div className="flex flex-col h-[60vh] sm:h-[500px]">
            {/* Chat Area */}
            <div className="flex-1 overflow-y-auto space-y-4 px-1 pb-4">
                {messages.map((msg, i) => (
                    <div 
                        key={i} 
                        className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}
                    >
                        <div 
                            className={`max-w-[85%] p-3.5 rounded-2xl text-sm leading-relaxed whitespace-pre-wrap ${
                                msg.role === 'user' 
                                    ? 'bg-zinc-800 text-white rounded-tr-sm shadow-md' 
                                    : 'bg-white dark:bg-zinc-800 text-slate-700 dark:text-slate-200 border border-gray-100 dark:border-white/10 rounded-tl-sm shadow-sm'
                            }`}
                        >
                            {msg.text}
                        </div>
                    </div>
                ))}
                {isTyping && (
                    <div className="flex justify-start animate-pulse">
                        <div className="bg-gray-100 dark:bg-zinc-800 px-4 py-3 rounded-2xl rounded-tl-sm flex gap-1 items-center">
                            <span className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                            <span className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                            <span className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce"></span>
                        </div>
                    </div>
                )}
                <div ref={messagesEndRef} />
            </div>

            {/* Input Area */}
            <div className="pt-3 border-t border-gray-100 dark:border-white/10 bg-white/50 dark:bg-black/20 backdrop-blur-sm -mx-2 px-2 pb-1">
                <form onSubmit={handleSendMessage} className="flex gap-2 items-center">
                    <input 
                        value={inputMsg}
                        onChange={e => setInputMsg(e.target.value)}
                        placeholder="Ask about products, warranty, or sales tips..."
                        className="flex-1 bg-white dark:bg-zinc-800 border border-gray-200 dark:border-zinc-700 rounded-full px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-black/20 dark:focus:ring-white/20 shadow-sm transition-all"
                        disabled={isTyping}
                    />
                    <button 
                        type="submit" 
                        disabled={!inputMsg.trim() || isTyping}
                        className="p-2.5 bg-black dark:bg-white text-white dark:text-black rounded-full shadow-lg hover:scale-105 active:scale-95 disabled:opacity-50 disabled:scale-100 transition-all"
                    >
                        <Send size={18} />
                    </button>
                </form>
            </div>
        </div>
      </Modal>

      {/* Image Zoom Modal */}
      {zoomedImage && (
          <div className="fixed inset-0 z-[60] bg-black/95 backdrop-blur-xl flex items-center justify-center p-2">
              <button 
                onClick={() => setZoomedImage(null)}
                className="absolute top-4 right-4 p-3 bg-white/10 rounded-full text-white hover:bg-white/20 z-50"
              >
                  <X size={24} />
              </button>
              <img 
                src={zoomedImage} 
                className="max-w-full max-h-[90vh] object-contain shadow-2xl rounded-lg"
                alt="Zoomed Bill"
              />
          </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { User, LogOut, FileText, Download, ExternalLink } from 'lucide-react';
import { GlassCard, GlassInput, GlassButton } from './ui/GlassComponents';
import { UserProfile } from '../types';
import { saveUser, logoutUser, getSales, compressImage } from '../services/storageService';
import { downloadCSV } from '../services/reportService';

interface SettingsProps {
  user: UserProfile;
  onUpdateUser: (u: UserProfile) => void;
  onLogout: () => void;
}

const Settings: React.FC<SettingsProps> = ({ user, onUpdateUser, onLogout }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(user);
  const [backupMonth, setBackupMonth] = useState('');

  const handleSave = () => {
    saveUser(editForm);
    onUpdateUser(editForm);
    setIsEditing(false);
  };

  const handleAvatarChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          try {
              const base64 = await compressImage(e.target.files[0]);
              setEditForm(prev => ({ ...prev, avatar: base64 }));
          } catch (err) {
              alert('Image too large');
          }
      }
  };

  const exportJSON = () => {
    const allSales = getSales();
    let salesToExport = allSales;

    if (backupMonth) {
        salesToExport = allSales.filter(s => s.date.startsWith(backupMonth));
    }

    if (salesToExport.length === 0) {
        alert("No data found for the selected month.");
        return;
    }

    const data = JSON.stringify({ user, sales: salesToExport }, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `backup_${user.name.split(' ')[0]}_${backupMonth || 'all'}.json`;
    a.click();
  };

  const handlePrintView = () => {
      // Create a print-friendly window
      const sales = getSales();
      const printWindow = window.open('', '_blank');
      if (printWindow) {
        printWindow.document.write(`
            <html>
                <head>
                    <title>Print Report</title>
                    <style>
                        body { font-family: sans-serif; padding: 20px; }
                        table { width: 100%; border-collapse: collapse; margin-top: 20px; }
                        th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
                        th { background-color: #f2f2f2; }
                        .header { margin-bottom: 20px; }
                        img { max-width: 100px; }
                    </style>
                </head>
                <body>
                    <div class="header">
                        <h1>Sales Report</h1>
                        <p><strong>Executive:</strong> ${user.name} (${user.employeeId})</p>
                        <p><strong>Store:</strong> ${user.storeName}</p>
                        <p><strong>Generated:</strong> ${new Date().toLocaleDateString()}</p>
                    </div>
                    <table>
                        <thead>
                            <tr>
                                <th>Date</th>
                                <th>Products</th>
                                <th>Total Qty</th>
                                <th>Total Value</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${sales.map(s => `
                                <tr>
                                    <td>${s.date}</td>
                                    <td>
                                        ${s.items.map(i => `<div>${i.productName} (${i.quantity} x ${i.price})</div>`).join('')}
                                    </td>
                                    <td>${s.totalQty}</td>
                                    <td>₹${s.totalValue}</td>
                                </tr>
                            `).join('')}
                        </tbody>
                    </table>
                    <script>window.print();</script>
                </body>
            </html>
        `);
        printWindow.document.close();
      }
  };

  return (
    <div className="space-y-6">
        {/* Profile Card */}
        <GlassCard className="p-6 text-center relative">
            <div className="relative inline-block">
                <div className="w-24 h-24 rounded-full overflow-hidden mx-auto border-4 border-white/50 shadow-xl mb-4">
                    {editForm.avatar ? (
                        <img src={editForm.avatar} className="w-full h-full object-cover" />
                    ) : (
                        <div className="w-full h-full bg-slate-200 flex items-center justify-center text-3xl font-bold text-slate-400">
                            {user.name.charAt(0)}
                        </div>
                    )}
                </div>
                {isEditing && (
                    <label className="absolute bottom-4 right-0 bg-blue-500 text-white p-1 rounded-full cursor-pointer shadow-lg">
                        <User size={16} />
                        <input type="file" className="hidden" accept="image/*" onChange={handleAvatarChange} />
                    </label>
                )}
            </div>

            {isEditing ? (
                <div className="space-y-3 text-left">
                    <GlassInput value={editForm.name} onChange={e => setEditForm({...editForm, name: e.target.value})} placeholder="Name" />
                    <GlassInput value={editForm.storeName} onChange={e => setEditForm({...editForm, storeName: e.target.value})} placeholder="Store" />
                    <GlassInput value={editForm.employeeId} onChange={e => setEditForm({...editForm, employeeId: e.target.value})} placeholder="Emp ID" />
                    <div className="flex gap-2 items-center">
                        <label className="whitespace-nowrap text-sm text-slate-500 w-24">Target (₹)</label>
                        <GlassInput type="number" value={editForm.monthlyTarget} onChange={e => setEditForm({...editForm, monthlyTarget: parseInt(e.target.value) || 0})} />
                    </div>
                    <div className="flex gap-2 pt-2">
                        <GlassButton onClick={handleSave} className="flex-1">Save</GlassButton>
                        <GlassButton onClick={() => { setIsEditing(false); setEditForm(user); }} variant="secondary" className="flex-1">Cancel</GlassButton>
                    </div>
                </div>
            ) : (
                <>
                    <h2 className="text-xl font-bold">{user.name}</h2>
                    <p className="text-slate-500">{user.storeName}</p>
                    <p className="text-xs text-slate-400 mt-1">ID: {user.employeeId}</p>
                    <button onClick={() => setIsEditing(true)} className="text-blue-500 text-sm mt-4 font-medium hover:underline">Edit Profile</button>
                </>
            )}
        </GlassCard>

        {/* Data Management */}
        <h3 className="font-bold text-lg px-2">Data & Reports</h3>
        <GlassCard className="p-4 space-y-4">
            <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-wide">Backup Month (Optional)</label>
                <input 
                    type="month" 
