  const handleCopyToday = () => {
      const todayStr = new Date().toISOString().split('T')[0];
      const todayReport = sales.find(s => s.date === todayStr);
      if(todayReport) {
          copyReport(todayReport);
      } else {
          alert('No entry found for today.');
      }
