                    </div>

                    <div className="grid grid-cols-7 gap-2">
                        {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map(d => (
                            <div key={d} className="text-center text-[10px] font-bold text-slate-400">{d}</div>
                        ))}
                        {calendarDays.map((d, i) => {
