                                        <button onClick={() => handleRemoveImage(selectedDateReport, idx)} className="px-3 py-1 bg-red-500 text-white text-xs rounded-full hover:bg-red-600 mt-2">
                                            Delete
                                        </button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
                </>
            )}

             {/* Actions */}
             <div className="grid grid-cols-2 gap-3 mt-6 sticky bottom-0 bg-white/0 pt-2">
                <GlassButton onClick={() => copyReport(selectedDateReport)} variant="primary">
                    Copy Report
                </GlassButton>
                <GlassButton variant="danger" onClick={() => handleDeleteEntry(selectedDateReport.date)}>
                    Delete All
                </GlassButton>
             </div>
          </div>
        )}
      </Modal>

      {/* Store EOD Modal */}
      <Modal 
        isOpen={showEODModal} 
        onClose={() => setShowEODModal(false)}
        title="Store EOD Report"
      >
        <div className="space-y-4">
            <div className="bg-blue-50 dark:bg-blue-900/20 p-3 rounded-xl mb-4">
                <p className="text-xs text-blue-600 dark:text-blue-300 font-semibold mb-1">Date: {formatToDisplayDate(getEODStats().dateStr)}</p>
                <p className="text-xs text-slate-500">Calculated stats are based on today's entries.</p>
