                            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; 
                            padding: 40px; 
                            color: #1e293b;
                            background: white;
                        }
                        .header { 
                            margin-bottom: 30px; 
                            border-bottom: 3px solid #6366f1; 
                            padding-bottom: 20px; 
                        }
                        .header h1 { 
                            margin: 0 0 10px 0; 
                            color: #1e1b4b; 
                            font-size: 28px;
                        }
                        .meta { 
                            display: grid; 
                            grid-template-columns: repeat(2, 1fr); 
                            gap: 15px; 
                            font-size: 14px;
                            color: #475569;
