                                                    <div class="bill-caption">Attachment ${idx + 1}</div>
                                                </div>
                                            `).join('')}
                                        </div>
                                    </div>
                                `;
                            }).join('')}
                        </div>
                    ` : ''}

                    <script>
                        window.onload = function() {
                            setTimeout(() => window.print(), 800);
                        }
                    </script>
                </body>
            </html>
        `);
        printWindow.document.close();
      }
  };

  return (
