import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';
import NewEntry from './components/NewEntry';
import EOD from './components/EOD';
import CRM from './components/CRM';
import Settings from './components/Settings';
import { Tab, UserProfile, DailyReport } from './types';
import { getUser, logoutUser, getSales, getTheme, saveTheme } from './services/storageService';

const App = () => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [isLoading, setIsLoading] = useState(true);
  const [salesData, setSalesData] = useState<DailyReport[]>([]);
  const [isDark, setIsDark] = useState(false);

  useEffect(() => {
    const savedTheme = getTheme();
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    if (savedTheme === 'dark' || (!savedTheme && prefersDark)) {
      setIsDark(true);
      document.documentElement.classList.add('dark');
    }

    const storedUser = getUser();
    if (storedUser) {
      setUser(storedUser);
      setSalesData(getSales());
    }
    // Sophisticated splash timeout
    setTimeout(() => setIsLoading(false), 2200);
  }, []);

  const toggleTheme = () => {
    const newMode = !isDark;
    setIsDark(newMode);
    if (newMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
    saveTheme(newMode ? 'dark' : 'light');
  };

  const handleLogin = (newUser: UserProfile) => {
    setUser(newUser);
  };

  const handleLogout = () => {
    logoutUser();
    setUser(null);
  };

  const refreshData = () => {
    setSalesData(getSales());
  };

  if (isLoading) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-white dark:bg-black transition-colors duration-700 overflow-hidden">
        {/* Animated background blobs */}
        <div className="absolute top-[-20%] left-[-10%] w-[100vw] h-[100vw] bg-indigo-500/10 rounded-full blur-[120px] animate-float opacity-50" />
        <div className="absolute bottom-[-20%] right-[-10%] w-[80vw] h-[80vw] bg-purple-500/10 rounded-full blur-[120px] animate-float opacity-50" style={{ animationDelay: '-3s' }} />

        <div className="relative z-10 flex flex-col items-center gap-8">
          {/* iOS Style Glass Icon */}
          <div className="relative group w-24 h-24">
