            <div className="relative h-full w-full bg-black dark:bg-white rounded-[22%] shadow-2xl flex items-center justify-center border border-white/20">
               <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" className="w-12 h-12 text-white dark:text-black">
                 <path d="M30 70 L50 30 L70 70" fill="none" stroke="currentColor" strokeWidth="8" strokeLinecap="round" strokeLinejoin="round" />
               </svg>
            </div>
          </div>

          <div className="text-center space-y-2">
            <h1 className="text-4xl font-extrabold tracking-tighter bg-clip-text text-transparent bg-gradient-to-b from-black to-zinc-600 dark:from-white dark:to-zinc-400">
              SalesTrack
            </h1>
            <div className="flex gap-1 justify-center mt-4">
              {[...Array(12)].map((_, i) => (
                <div 
                  key={i} 
                  className="w-1.5 h-4 bg-zinc-900 dark:bg-white rounded-full animate-ios-loader" 
                  style={{ 
                    animationDelay: `${i * 0.1}s`,
                    transform: `rotate(${i * 30}deg) translateY(-8px)` 
                  }} 
                />
              ))}
            </div>
          </div>
        </div>

        <p className="absolute bottom-12 text-[10px] font-bold tracking-[0.3em] uppercase text-zinc-400 animate-pulse">
          Excellence in Motion
        </p>
      </div>
    );
  }

  if (!user) return <Auth onLogin={handleLogin} />;

  return (
    <Layout 
      activeTab={activeTab} 
      onTabChange={setActiveTab}
      isDark={isDark}
      toggleTheme={toggleTheme}
      user={user}
      salesData={salesData}
    >
      {activeTab === 'dashboard' && <Dashboard sales={salesData} user={user} onDataChange={refreshData} onUpdateUser={setUser} />}
      {activeTab === 'entry' && <NewEntry user={user} onEntryComplete={refreshData} />}
      {activeTab === 'eod' && <EOD user={user} onUpdateUser={setUser} />}
      {activeTab === 'crm' && <CRM />}
      {activeTab === 'settings' && <Settings user={user} onUpdateUser={setUser} onLogout={handleLogout} />}
    </Layout>
  );
};

