interface NewEntryProps {
  user: UserProfile;
  onEntryComplete: () => void;
}

const NewEntry: React.FC<NewEntryProps> = ({ user, onEntryComplete }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [items, setItems] = useState<SaleItem[]>([
    { id: '1', productName: '', quantity: 1, price: 0 }
  ]);
  const [inputModes, setInputModes] = useState<('unit'|'total')[]>(['unit']);

  const [billImages, setBillImages] = useState<string[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showSuccessModal, setShowSuccessModal] = useState(false);

  // Week Off Logic
  const [isWeekOff, setIsWeekOff] = useState(false);

  // Search State
  const [activeSearchIndex, setActiveSearchIndex] = useState<number | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const filteredProducts = searchTerm 
      ? PRODUCT_LIST.filter(p => p.toLowerCase().includes(searchTerm.toLowerCase()))
      : PRODUCT_LIST;

  const addItem = () => {
    setItems([...items, { id: Date.now().toString(), productName: '', quantity: 1, price: 0 }]);
    setInputModes([...inputModes, 'unit']);
  };

  const removeItem = (index: number) => {
    if (items.length === 1) return;
    const newItems = [...items];
    newItems.splice(index, 1);
    setItems(newItems);

    const newModes = [...inputModes];
    newModes.splice(index, 1);
    setInputModes(newModes);
  };

  const updateItem = (index: number, field: keyof SaleItem, value: string | number) => {
    const newItems = [...items];
    newItems[index] = { ...newItems[index], [field]: value };
    setItems(newItems);
  };

  const updatePrice = (index: number, value: number) => {
      const mode = inputModes[index];
      const qty = items[index].quantity || 1;

      if (mode === 'total') {
          // User input is Total Price, so Unit Price = Total / Qty
          updateItem(index, 'price', value / qty);
      } else {
          // User input is Unit Price
          updateItem(index, 'price', value);
      }
  };

  const togglePriceMode = (index: number) => {
      const newModes = [...inputModes];
      newModes[index] = newModes[index] === 'unit' ? 'total' : 'unit';
      setInputModes(newModes);

      // Reset price to 0 to avoid confusion when switching modes
      updateItem(index, 'price', 0);
  };

  const handleProductSelect = (index: number, name: string) => {
      updateItem(index, 'productName', name);
      setActiveSearchIndex(null);
      setSearchTerm('');
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      try {
        const files = Array.from(e.target.files);
        const newImages = await Promise.all(files.map(f => compressImage(f as File)));
        setBillImages(prev => [...prev, ...newImages]);
      } catch (err) {
        alert('Error uploading images');
      }
    }
  };

  const removeImage = (index: number) => {
      setBillImages(prev => prev.filter((_, i) => i !== index));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (isWeekOff) {
        if(confirm("Mark " + formatToDisplayDate(date) + " as Week Off?")) {
            setIsSubmitting(true);
            setTimeout(() => {
                const sales = getSales();
                const existingIndex = sales.findIndex(s => s.date === date);
                if(existingIndex > -1) {
                     sales[existingIndex] = {
                         ...sales[existingIndex],
                         isWeekOff: true,
                         items: [],
                         totalQty: 0,
                         totalValue: 0
                     }
                } else {
                    sales.push({
                        date,
                        items: [],
                        totalQty: 0,
                        totalValue: 0,
                        isWeekOff: true
                    });
                }
                localStorage.setItem('app_sales_data', JSON.stringify(sales));

                setIsSubmitting(false);
                setShowSuccessModal(true);
            }, 500);
        }
        return;
    }

    if (billImages.length === 0 && !confirm("Save without bill image?")) return;

    setIsSubmitting(true);
    setTimeout(() => {
        saveSaleEntry(date, items, billImages);
        setIsSubmitting(false);
        setShowSuccessModal(true);
    }, 500);
  };

  const handleShareWhatsApp = () => {
      if(isWeekOff) return;
      const allSales = getSales();
      const report = allSales.find(s => s.date === date);
      if (report) {
          const text = generateTextReport(user, report);
          window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
      }
  };

  const handleCopyText = () => {
      if(isWeekOff) {
          navigator.clipboard.writeText(`Name: ${user.name}\nDate: ${formatToDisplayDate(date)}\nStatus: Week Off`);
          alert('Week Off report copied');
          return;
      }
      const allSales = getSales();
      const report = allSales.find(s => s.date === date);
      if (report) {
          const text = generateTextReport(user, report);
          navigator.clipboard.writeText(text);
          alert('Report copied!');
      }
  };

  const resetForm = () => {
      setItems([{ id: Date.now().toString(), productName: '', quantity: 1, price: 0 }]);
      setInputModes(['unit']);
      setBillImages([]);
      setDate(new Date().toISOString().split('T')[0]);
      setIsWeekOff(false);
      setShowSuccessModal(false);
      onEntryComplete();
  };

  const totalValue = items.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  const formattedDate = formatToDisplayDate(date);

  return (
    <>
    <div className="space-y-6 animate-in slide-in-from-bottom-5 fade-in duration-500">
      <div className="text-center mb-6">
        <h2 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-purple-600">New Entry</h2>
        <p className="text-slate-500 text-sm">Log your daily performance</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Date & Status Card */}
        <GlassCard className="p-4">
          <div className="flex justify-between items-center gap-4">
             <div className="flex-1 space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-wide">Date</label>
                {/* Visual Overlay to force DD/MM/YYYY look */}
                <div className="relative w-full h-10 bg-slate-100 dark:bg-zinc-800 rounded-xl px-3 flex items-center shadow-inner">
                    <span className="font-medium text-sm text-slate-800 dark:text-zinc-200 pointer-events-none">
                        {formatToDisplayDate(date)}
                    </span>
                    <input 
                        type="date" 
                        value={date} 
                        onChange={e => setDate(e.target.value)}
                        required
                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                    />
                </div>
             </div>
             <div className="flex flex-col items-end space-y-2">
                 <span className="text-xs font-bold text-slate-500 uppercase tracking-wide">Status</span>
                 <label className="relative inline-flex items-center cursor-pointer">
                    <input type="checkbox" className="sr-only peer" checked={isWeekOff} onChange={e => setIsWeekOff(e.target.checked)} />
                    <div className="w-12 h-7 bg-gray-200 peer-focus:outline-none rounded-full peer dark:bg-zinc-700 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-6 after:w-6 after:transition-all dark:border-gray-600 peer-checked:bg-blue-600 shadow-inner"></div>
                    <span className="ml-2 text-xs font-semibold text-gray-500 dark:text-gray-400 w-12">{isWeekOff ? 'OFF' : 'Work'}</span>
                </label>
             </div>
          </div>
        </GlassCard>

        {!isWeekOff && (
        <div className="space-y-4">
            <div className="flex justify-between items-end px-1">
                <label className="text-sm font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wide">Products</label>
                <button type="button" onClick={addItem} className="text-blue-600 dark:text-blue-400 text-sm font-semibold flex items-center gap-1 hover:opacity-80 transition-opacity">
                    <Plus size={16} /> Add Item
                </button>
            </div>

            {items.map((item, index) => {
              const mode = inputModes[index];
              const displayPrice = mode === 'total' 
                  ? (item.price * item.quantity)
                  : item.price;
              const calculatedTotal = item.price * item.quantity;

              return (
              <div key={item.id} className="relative bg-white/40 dark:bg-zinc-900/40 backdrop-blur-xl rounded-2xl border border-white/30 dark:border-white/10 shadow-sm animate-in zoom-in-95 duration-200 overflow-hidden">
                {items.length > 1 && (
                    <button 
                        type="button" 
                        onClick={() => removeItem(index)}
                        className="absolute top-2 right-2 w-7 h-7 flex items-center justify-center bg-red-100 dark:bg-red-900/30 text-red-500 rounded-full shadow-md hover:bg-red-200 transition-colors z-10"
                    >
                        <Trash2 size={14} />
                    </button>
                )}

                <div className="p-5 space-y-4">
                    {/* Product Name Search */}
                    <div className="space-y-1.5 relative z-20">
                        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider ml-1">Product Model</label>
                        <div className="relative">
                            <div 
                                className="flex items-center justify-between w-full bg-white/50 dark:bg-black/20 border border-white/20 dark:border-white/5 rounded-xl px-4 py-3 cursor-pointer hover:bg-white/70 transition-colors"
                                onClick={() => {
                                    setActiveSearchIndex(index);
                                    setSearchTerm(item.productName);
                                }}
                            >
                                <span className={`text-sm font-medium ${!item.productName && 'text-slate-400 italic'}`}>
                                    {item.productName || 'Select Product...'}
                                </span>
                                <ChevronDown size={16} className="text-slate-400" />
                            </div>

                            {activeSearchIndex === index && (
                                <div className="absolute top-full left-0 right-0 mt-2 bg-white/95 dark:bg-zinc-900/95 backdrop-blur-xl rounded-xl shadow-2xl border border-gray-100 dark:border-white/10 max-h-60 overflow-hidden flex flex-col animate-in fade-in zoom-in-95 duration-150 z-50">
                                    <div className="p-2 border-b border-gray-100 dark:border-white/5 sticky top-0 bg-white/90 dark:bg-zinc-900/90 backdrop-blur">
                                        <div className="flex items-center gap-2 bg-gray-100 dark:bg-black/40 rounded-lg px-3 py-1.5">
                                            <Search size={14} className="text-gray-400" />
                                            <input 
                                                autoFocus
                                                className="w-full py-1 text-sm outline-none bg-transparent"
                                                placeholder="Search model..."
                                                value={searchTerm}
                                                onChange={e => setSearchTerm(e.target.value)}
                                            />
                                            {searchTerm && <X size={14} className="text-gray-400 cursor-pointer" onClick={() => setSearchTerm('')} />}
                                        </div>
                                    </div>
                                    <div className="overflow-y-auto custom-scrollbar">
                                        {filteredProducts.map(p => (
                                            <div 
                                                key={p} 
                                                className="px-4 py-3 text-sm hover:bg-blue-50 dark:hover:bg-white/10 cursor-pointer border-b border-gray-50 dark:border-white/5 last:border-0"
                                                onClick={() => handleProductSelect(index, p)}
                                            >
                                                {p}
                                            </div>
                                        ))}
                                        {searchTerm && !filteredProducts.includes(searchTerm) && (
                                            <div 
                                                className="px-4 py-3 text-sm text-blue-600 cursor-pointer font-bold bg-blue-50/50"
                                                onClick={() => handleProductSelect(index, searchTerm)}
                                            >
                                                + Add "{searchTerm}"
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}
                            {/* Backdrop for search */}
                            {activeSearchIndex === index && (
                                <div className="fixed inset-0 z-40 bg-black/5" onClick={() => setActiveSearchIndex(null)} />
                            )}
                        </div>
                    </div>

                    {/* Qty & Price Row - Using Grid for alignment */}
                    <div className="grid grid-cols-2 gap-4">
                        {/* Column 1: Quantity */}
                        <div className="space-y-1.5">
                            <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider ml-1">Quantity</label>
                            <input 
                                type="number"
                                min="1"
                                className="w-full bg-white/50 dark:bg-black/20 border-b-2 border-slate-200 dark:border-slate-700 focus:border-blue-500 rounded-t-lg px-3 py-2.5 text-center font-mono text-lg font-semibold outline-none transition-all h-12"
                                value={item.quantity}
                                onChange={e => updateItem(index, 'quantity', parseInt(e.target.value) || 0)}
                                required
                            />
                        </div>

                        {/* Column 2: Price (Unit or Total based on mode) */}
                        <div className="space-y-1.5 relative">
                             <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider ml-1">
                                {mode === 'total' ? 'Total Amount' : 'Unit Price'}
                            </label>
                            <div className="relative">
                                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-medium z-10">₹</span>
                                <input 
                                    type="number"
                                    min="0"
                                    step="any"
                                    className={`w-full bg-white/50 dark:bg-black/20 border-b-2 rounded-t-lg pl-8 pr-3 py-2.5 font-mono text-lg font-semibold outline-none transition-all h-12 ${
                                        mode === 'total' ? 'border-purple-300 focus:border-purple-500 text-purple-700 dark:text-purple-300' : 'border-slate-200 dark:border-slate-700 focus:border-blue-500'
                                    }`}
                                    value={displayPrice || ''}
                                    onChange={e => updatePrice(index, parseFloat(e.target.value) || 0)}
                                    required
                                />
                            </div>
                        </div>
                    </div>
                </div>

                {/* Footer Logic for Calculation Mode */}
                <div className="bg-slate-50/50 dark:bg-black/30 border-t border-white/20 dark:border-white/5 p-3 flex justify-between items-center">
                    <div className="text-xs text-slate-500 dark:text-slate-400 font-medium px-2">
                        Total: <span className="text-slate-800 dark:text-white font-bold ml-1">₹{calculatedTotal.toLocaleString()}</span>
                    </div>

                    <button 
                        type="button" 
                        onClick={() => togglePriceMode(index)}
                        className="text-[10px] font-bold uppercase tracking-wide flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-white dark:bg-zinc-800 border border-slate-200 dark:border-zinc-700 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-zinc-700 transition-colors shadow-sm"
                    >
                        <RefreshCcw size={10} className={mode === 'total' ? 'text-purple-500' : ''} />
                        {mode === 'total' ? 'Input Unit Price' : 'Input Total Amount'}
                    </button>
                </div>

              </div>
            )})}
          </div>
          )}

        {/* Bill Images Section - Hide if Week Off */}
        {!isWeekOff && (
        <GlassCard className="p-5">
            <div className="flex justify-between items-center mb-4">
                <div>
                    <p className="font-bold text-slate-700 dark:text-slate-200">Bill Copies</p>
                    <p className="text-xs text-slate-500">{billImages.length} images selected</p>
                </div>
                <div className="flex gap-2">
                    <label className="cursor-pointer bg-slate-100 dark:bg-zinc-800 text-slate-600 dark:text-slate-300 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-wide flex items-center gap-1.5 hover:bg-slate-200 dark:hover:bg-zinc-700 transition-colors">
                        <Camera size={14} /> Add
                        <input type="file" multiple accept="image/*" onChange={handleImageUpload} className="hidden" />
                    </label>
                </div>
            </div>

            {billImages.length === 0 ? (
                <div className="border-2 border-dashed border-slate-300 dark:border-slate-700 rounded-xl p-8 flex flex-col items-center justify-center text-slate-400 gap-2 bg-slate-50/50 dark:bg-black/20">
                    <ImageIcon size={32} strokeWidth={1.5} />
                    <p className="text-xs font-medium">No bills uploaded</p>
                </div>
            ) : (
                <div className="flex gap-3 overflow-x-auto pb-2 snap-x scrollbar-hide">
                    {billImages.map((img, idx) => (
                        <div key={idx} className="relative flex-shrink-0 w-24 h-32 snap-start group">
                            <img src={img} alt={`Bill ${idx}`} className="w-full h-full object-cover rounded-xl border border-slate-200 dark:border-white/10 shadow-sm" />
                            <button 
                                type="button"
                                onClick={() => removeImage(idx)}
                                className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 shadow-md opacity-0 group-hover:opacity-100 transition-opacity"
                            >
                                <X size={12} />
                            </button>
                            <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/50 to-transparent p-2 rounded-b-xl">
                                <span className="text-[10px] text-white font-bold opacity-80">#{idx + 1}</span>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </GlassCard>
        )}

        {!isWeekOff && (
        <div className="bg-white/60 dark:bg-blue-900/20 backdrop-blur-xl border border-white/40 dark:border-blue-500/30 rounded-2xl p-4 flex justify-between items-center shadow-lg">
            <span className="text-sm font-semibold text-slate-600 dark:text-slate-300 uppercase tracking-wide">Total Value</span>
            <span className="text-3xl font-bold text-blue-600 dark:text-blue-400 tracking-tight">₹{totalValue.toLocaleString()}</span>
        </div>
        )}

        <GlassButton type="submit" className="w-full py-4 text-lg shadow-xl shadow-blue-500/20" disabled={isSubmitting}>
            {isSubmitting ? 'Saving Entry...' : (isWeekOff ? 'Mark as Week Off' : 'Save Entry')}
        </GlassButton>
      </form>
    </div>

    {/* Success Modal */}
    <Modal 
        isOpen={showSuccessModal} 
        onClose={resetForm} 
        title={isWeekOff ? "Week Off Recorded" : "Entry Saved!"}
    >
        <div className="text-center space-y-6 pt-4">
            <div className={`w-20 h-20 rounded-full flex items-center justify-center mx-auto shadow-xl ${isWeekOff ? 'bg-gray-100 text-gray-500' : 'bg-gradient-to-tr from-green-400 to-emerald-600 text-white'}`}>
                {isWeekOff ? <Check size={40} /> : <Check size={40} strokeWidth={3} />}
            </div>
            <p className="text-slate-600 dark:text-slate-300 font-medium">
                {isWeekOff 
                    ? `Marked ${formattedDate} as Week Off.` 
                    : `Your data has been added to the cumulative report for ${formattedDate}.`
                }
            </p>

            {!isWeekOff && (
            <div className="grid grid-cols-2 gap-4">
                <button 
                    onClick={handleShareWhatsApp}
                    className="flex flex-col items-center justify-center gap-2 p-4 rounded-2xl bg-[#25D366]/10 text-[#25D366] hover:bg-[#25D366]/20 transition-all border border-[#25D366]/20 hover:scale-[1.02]"
                >
                    <Send size={24} />
                    <span className="font-bold text-sm">WhatsApp</span>
                </button>
                <button 
                    onClick={handleCopyText}
                    className="flex flex-col items-center justify-center gap-2 p-4 rounded-2xl bg-blue-500/10 text-blue-500 hover:bg-blue-500/20 transition-all border border-blue-500/20 hover:scale-[1.02]"
                >
                    <Copy size={24} />
                    <span className="font-bold text-sm">Copy</span>
                </button>
            </div>
            )}

            <GlassButton onClick={resetForm} variant="secondary" className="w-full">
                Close & New Entry
            </GlassButton>
        </div>
    </Modal>
    </>
  );
};

export default NewEntry;

import React, { useState, useMemo, useEffect } from 'react';
import { Send, Target, TrendingUp, Calendar, Copy, Check, ChevronLeft, ChevronRight, List, Calendar as CalendarIcon, Trash2, X, AlertCircle } from 'lucide-react';
import { GlassCard, GlassInput, GlassButton, Modal } from './ui/GlassComponents';
import { UserProfile, StoreEODEntry } from '../types';
import { saveUser, getEODEntries, saveEODEntry, deleteEODEntry } from '../services/storageService';
import { generateStoreEODReport, formatToDisplayDate } from '../services/reportService';

interface EODProps {
    user: UserProfile;
    onUpdateUser: (u: UserProfile) => void;
}

const EOD: React.FC<EODProps> = ({ user, onUpdateUser }) => {
    const [viewMode, setViewMode] = useState<'entry' | 'calendar'>('entry');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [achievement, setAchievement] = useState<number>(0);
    const [eolAchieve, setEolAchieve] = useState<number>(0);
    const [showSuccess, setShowSuccess] = useState(false);
    const [eodHistory, setEodHistory] = useState<StoreEODEntry[]>(getEODEntries());

    // Targets (Persistent in user profile)
    const [weeklyTarget, setWeeklyTarget] = useState(user.customTargets?.weekly || 0);
    const [eolTarget, setEolTarget] = useState(user.customTargets?.eol || 0);

    // Calendar Navigation State
    const [currentMonth, setCurrentMonth] = useState(new Date());

    // Sync form when date changes or history loads
    useEffect(() => {
        const entry = eodHistory.find(e => e.date === date);
        if (entry) {
            setAchievement(entry.achievement);
            setEolAchieve(entry.eolAchieve);
            setWeeklyTarget(entry.weekTarget);
            setEolTarget(entry.eolTarget);
        } else {
            setAchievement(0);
            setEolAchieve(0);
        }
    }, [date, eodHistory]);

    // Daily target calculation
    const dailyTarget = Math.round(weeklyTarget / 7);

    // Weekly Cumulative Logic (Monday to Sunday)
    const calculateWeeklyAch = (targetDate: string) => {
        const d = new Date(targetDate);
        const day = d.getDay(); // 0 (Sun) to 6 (Sat)
        const diff = (day + 6) % 7; 

        const monday = new Date(d);
        monday.setDate(d.getDate() - diff);
        monday.setHours(0,0,0,0);

        const mondayStr = monday.toISOString().split('T')[0];

        let total = eodHistory.reduce((acc, entry) => {
            if (entry.date >= mondayStr && entry.date <= targetDate) {
                const isCurrentBeingEdited = entry.date === date;
                // If the entry we are looking at in history is the SAME date we are editing,
                // we prefer the live input value for the calculation.
                return isCurrentBeingEdited ? acc : acc + entry.achievement;
            }
            return acc;
        }, 0);

        // Always add the live achievement value for the currently selected date
        total += achievement;

        return total;
    };

    const handleShare = () => {
        const entry: StoreEODEntry = {
            date,
            achievement,
            eolAchieve,
            dayTarget: dailyTarget,
            weekTarget: weeklyTarget,
            eolTarget: eolTarget
        };

        saveEODEntry(entry);

        const updatedUser = {
            ...user,
            customTargets: {
                weekly: weeklyTarget,
                daily: dailyTarget,
                eol: eolTarget
            }
        };
        saveUser(updatedUser);
        onUpdateUser(updatedUser);

        setEodHistory(getEODEntries());

        const weekAch = calculateWeeklyAch(date);
        const reportText = generateStoreEODReport(
            user,
            date,
            dailyTarget,
            achievement,
            weeklyTarget,
            weekAch,
            eolTarget,
            eolAchieve
        );

        window.open(`https://wa.me/?text=${encodeURIComponent(reportText)}`, '_blank');
        setShowSuccess(true);
    };

    const handleDelete = (d: string) => {
        if (confirm("Delete this EOD record?")) {
            deleteEODEntry(d);
            setEodHistory(getEODEntries());
        }
    };

    // Calendar Days
    const calendarDays = useMemo(() => {
        const year = currentMonth.getFullYear();
        const month = currentMonth.getMonth();
        const daysInMonth = new Date(year, month + 1, 0).getDate();
        const firstDay = new Date(year, month, 1).getDay();

        const days = [];
        for (let i = 0; i < firstDay; i++) days.push(null);
        for (let i = 1; i <= daysInMonth; i++) {
            const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
            days.push({ day: i, dateStr });
        }
        return days;
    }, [currentMonth]);

    const weekAch = useMemo(() => calculateWeeklyAch(date), [date, achievement, eodHistory]);
    const dailyRemaining = Math.max(0, dailyTarget - achievement);
    const weeklyRemaining = Math.max(0, weeklyTarget - weekAch);
    const progress = dailyTarget > 0 ? Math.min((achievement / dailyTarget) * 100, 100) : 0;

    return (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="text-center">
                <h2 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-purple-600">Store EOD</h2>
                <p className="text-slate-500 text-sm">Target vs Achievement Tracking</p>
            </div>

            <div className="flex p-1 bg-white/40 dark:bg-white/10 rounded-xl backdrop-blur-sm w-fit mx-auto border border-white/20">
                <button 
                    onClick={() => setViewMode('entry')}
                    className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'entry' ? 'bg-black text-white shadow-lg' : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'}`}
                >
                    Manual Entry
                </button>
                <button 
                    onClick={() => setViewMode('calendar')}
                    className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${viewMode === 'calendar' ? 'bg-black text-white shadow-lg' : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'}`}
                >
                    History View
                </button>
            </div>

            {viewMode === 'entry' ? (
                <>
                    <GlassCard className="p-5 space-y-5 shadow-xl">
                        <div className="flex items-center gap-3 border-b border-gray-100 dark:border-white/10 pb-3 relative">
                            <div className="p-2 bg-blue-500/10 rounded-lg text-blue-500 pointer-events-none">
                                <CalendarIcon size={20} />
                            </div>
                            <div className="flex-1 relative">
                                <span className="absolute inset-0 flex items-center font-bold text-lg pointer-events-none text-slate-800 dark:text-white">
                                    {formatToDisplayDate(date)}
                                </span>
                                <input 
                                    type="date" 
                                    value={date} 
                                    onChange={e => setDate(e.target.value)}
                                    className="opacity-0 absolute inset-0 w-full h-full cursor-pointer"
                                />
                            </div>
                            <ChevronRight size={16} className="text-slate-400 transform rotate-90" />
                        </div>

                        <div className="grid grid-cols-1 gap-6">
                            <div className="space-y-2">
                                <label className="text-[11px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                                    <Target size={14} className="text-purple-500" /> Weekly Target (₹)
                                </label>
                                <GlassInput 
                                    type="number"
                                    placeholder="Enter weekly goal"
                                    value={weeklyTarget || ''}
                                    onChange={e => setWeeklyTarget(parseInt(e.target.value) || 0)}
                                    className="font-mono text-lg"
                                />
                                <div className="flex justify-between items-center px-1">
                                    <p className="text-[10px] text-blue-500 font-bold">Daily: ₹{dailyTarget.toLocaleString()}</p>
                                    {weeklyRemaining > 0 && (
                                        <p className="text-[10px] text-orange-500 font-bold">Week Left: ₹{weeklyRemaining.toLocaleString()}</p>
                                    )}
                                </div>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[11px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                                    <TrendingUp size={14} className="text-green-500" /> Today Achievement (₹)
                                </label>
                                <GlassInput 
                                    type="number"
                                    placeholder="Amount (₹)"
                                    value={achievement || ''}
                                    onChange={e => setAchievement(parseInt(e.target.value) || 0)}
                                    className="border-green-200 dark:border-green-500/30 font-bold text-2xl font-mono text-green-700 dark:text-green-400 h-14"
                                />
                                {dailyRemaining > 0 && (
                                    <div className="flex items-center gap-1.5 px-1 text-[10px] font-bold text-orange-500">
                                        <AlertCircle size={10} />
                                        <span>Remaining to reach daily target: ₹{dailyRemaining.toLocaleString()}</span>
                                    </div>
                                )}
                            </div>
                        </div>

                        <div className="pt-2 px-1">
                            <div className="flex justify-between text-[11px] font-bold uppercase text-slate-400 mb-2">
                                <span className="flex items-center gap-1">Today's Progress</span>
                                <span className={progress >= 100 ? 'text-green-500' : ''}>{Math.round(progress)}%</span>
                            </div>
                            <div className="h-4 w-full bg-slate-100 dark:bg-zinc-800 rounded-full overflow-hidden p-0.5 border dark:border-white/5 shadow-inner">
                                <div 
                                    className={`h-full rounded-full transition-all duration-1000 ease-out relative ${progress >= 100 ? 'bg-gradient-to-r from-green-400 to-emerald-600' : 'bg-gradient-to-r from-blue-500 to-indigo-600'}`}
                                    style={{ width: `${progress}%` }}
                                >
                                    <div className="absolute inset-0 bg-white/20 animate-shine" />
                                </div>
                            </div>
                        </div>
                    </GlassCard>

                    <GlassCard className="p-5 space-y-4">
                        <div className="flex items-center justify-between mb-2">
                            <h3 className="font-bold text-sm text-slate-500 uppercase tracking-widest">EOL REPORT</h3>
                            <span className="text-[10px] bg-zinc-100 dark:bg-zinc-800 px-2 py-0.5 rounded text-slate-400">Optional</span>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-1">
                                <label className="text-[10px] font-bold text-slate-400 uppercase">Target</label>
                                <GlassInput 
                                    type="number"
                                    value={eolTarget || ''}
                                    onChange={e => setEolTarget(parseInt(e.target.value) || 0)}
                                    placeholder="0"
                                    className="h-10 text-sm"
                                />
                            </div>
                            <div className="space-y-1">
                                <label className="text-[10px] font-bold text-slate-400 uppercase">Achieved</label>
                                <GlassInput 
                                    type="number"
                                    value={eolAchieve || ''}
                                    onChange={e => setEolAchieve(parseInt(e.target.value) || 0)}
                                    placeholder="0"
                                    className="h-10 text-sm"
                                />
                            </div>
                        </div>
                    </GlassCard>

                    <GlassButton onClick={handleShare} className="w-full py-4 text-lg">
                        <Send size={20} /> Generate & Share WhatsApp
                    </GlassButton>
                </>
            ) : (
                <GlassCard className="p-4 space-y-6">
                    <div className="flex items-center justify-between px-2">
                        <button onClick={() => setCurrentMonth(new Date(currentMonth.setMonth(currentMonth.getMonth()-1)))} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-white/10">
                            <ChevronLeft size={20} />
                        </button>
                        <h3 className="font-bold text-lg">
                            {currentMonth.toLocaleString('default', { month: 'long', year: 'numeric' })}
                        </h3>
                        <button onClick={() => setCurrentMonth(new Date(currentMonth.setMonth(currentMonth.getMonth()+1)))} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-white/10">
                            <ChevronRight size={20} />
                        </button>
                    </div>

                    <div className="grid grid-cols-7 gap-2">
                        {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map(d => (
                            <div key={d} className="text-center text-[10px] font-bold text-slate-400">{d}</div>
                        ))}
                        {calendarDays.map((d, i) => {
                            if (!d) return <div key={i} />;
                            const entry = eodHistory.find(e => e.date === d.dateStr);
                            const isToday = d.dateStr === new Date().toISOString().split('T')[0];
                            const isAchieved = entry && entry.achievement >= entry.dayTarget;

                            return (
                                <div 
                                    key={d.dateStr}
                                    onClick={() => { setDate(d.dateStr); setViewMode('entry'); }}
                                    className={`aspect-square rounded-xl border flex flex-col items-center justify-center cursor-pointer transition-all relative
                                        ${isToday ? 'border-blue-500 ring-2 ring-blue-100 dark:ring-blue-900/30' : 'border-transparent hover:bg-slate-50 dark:hover:bg-white/5'}
                                        ${entry ? 'bg-white dark:bg-zinc-800 shadow-sm border-gray-100 dark:border-white/5' : 'bg-transparent'}
                                    `}
                                >
                                    <span className={`text-xs ${isToday ? 'font-bold text-blue-600' : 'text-slate-500'}`}>{d.day}</span>
                                    {entry && (
                                        <div className={`w-1.5 h-1.5 rounded-full mt-1 ${isAchieved ? 'bg-green-500' : 'bg-blue-400'}`} />
                                    )}
                                </div>
                            );
                        })}
                    </div>

                    <div className="space-y-3 pt-4 border-t border-gray-100 dark:border-white/5">
                        <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest px-1">Recent Records</h4>
                        {eodHistory
                            .filter(e => e.date.startsWith(currentMonth.toISOString().slice(0, 7)))
                            .sort((a,b) => b.date.localeCompare(a.date))
                            .map(entry => (
                                <div key={entry.date} className="flex justify-between items-center p-3 bg-white/40 dark:bg-white/5 rounded-xl border border-white/20">
                                    <div>
                                        <p className="text-sm font-bold">{formatToDisplayDate(entry.date)}</p>
                                        <p className="text-[10px] text-slate-500">Achieved: ₹{entry.achievement.toLocaleString()}</p>
                                    </div>
                                    <div className="flex items-center gap-4">
                                        <div className={`px-2 py-0.5 rounded text-[10px] font-bold ${entry.achievement >= entry.dayTarget ? 'bg-green-100 text-green-600' : 'bg-blue-100 text-blue-600'}`}>
                                            {Math.round((entry.achievement / entry.dayTarget) * 100)}%
                                        </div>
                                        <button onClick={() => handleDelete(entry.date)} className="text-red-400 hover:text-red-600">
                                            <Trash2 size={16} />
                                        </button>
                                    </div>
                                </div>
                            ))
                        }
                    </div>
                </GlassCard>
            )}

            <Modal isOpen={showSuccess} onClose={() => setShowSuccess(false)} title="Success">
                <div className="text-center space-y-4">
                    <div className="w-16 h-16 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center mx-auto text-green-600">
                        <Check size={32} />
                    </div>
                    <p className="text-sm font-medium">Store EOD targets and achievement updated for {formatToDisplayDate(date)}.</p>
                    <GlassButton onClick={() => setShowSuccess(false)} variant="secondary" className="w-full">Done</GlassButton>
                </div>
            </Modal>
        </div>
    );
};

