                                <tr>
                                    <td>${s.date.split('-').reverse().join('/')}</td>
                                    <td>${s.isWeekOff ? 'Week Off' : s.items.map(i => `${i.productName} (${i.quantity}x₹${i.price})`).join('<br>')}</td>
