    if (!pendingBackupData) return;

    const result = importFullBackup(pendingBackupData);
    if (result.success) {
      // Small delay to let user see success state if we added one, 
      // but nuclear reload is best for localstorage consistency.
      window.location.reload();
    } else {
      alert(result.message);
      setShowRestoreModal(false);
    }
  };

  const handlePrintView = () => {
      const allSales = getSales();
      let salesToPrint = allSales;

      if (backupMonth) {
          salesToPrint = allSales.filter(s => s.date.startsWith(backupMonth));
