    app: 'SalesTrack',
    version: '7.0.0',
    timestamp: new Date().toISOString(),
    data: {
      user: getUser(),
      sales: await getSales(),
      eod: await getEODEntries(),
      crm: await getComplaints(),
      theme: localStorage.getItem(LS_KEYS.THEME) || 'light'
    }
  };
