    const value = currentMonthSales.reduce((sum, s) => sum + s.totalValue, 0);
    const percentage = user.monthlyTarget > 0 ? Math.min((value / user.monthlyTarget) * 100, 100) : 0;
    const bal = Math.max(user.monthlyTarget - value, 0);
    return { mtdValue: value, mtdPercentage: percentage, balance: bal, monthName: now.toLocaleString('default', { month: 'long', year: 'numeric' }) };
  }, [sales, user.monthlyTarget, currentMonth]);

  const calendarDays = useMemo(() => {
    const now = currentMonth;
    const year = now.getFullYear();
    const month = now.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const firstDay = new Date(year, month, 1).getDay();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= daysInMonth; i++) {
      const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
      days.push({ day: i, dateStr });
    }
    return days;
  }, [currentMonth]);

  const nextMonth = () => { setCurrentMonth(prev => { const next = new Date(prev); next.setMonth(prev.getMonth() + 1); return next; }); };
  const prevMonth = () => { setCurrentMonth(prev => { const prevDate = new Date(prev); prevDate.setMonth(prev.getMonth() - 1); return prevDate; }); };

  const filteredSales = useMemo(() => {
      if (viewMode === 'calendar') return sales;
      return sales.filter(report => {
          if (filters.date && report.date !== filters.date) return false;
          if (filters.productName || filters.minQty || filters.minPrice) {
             const hasMatchingItem = report.items.some(item => {
                 const nameMatch = !filters.productName || item.productName.toLowerCase().includes(filters.productName.toLowerCase());
                 const qtyMatch = !filters.minQty || item.quantity >= parseInt(filters.minQty);
                 const priceMatch = !filters.minPrice || item.price >= parseFloat(filters.minPrice);
                 return nameMatch && qtyMatch && priceMatch;
             });
             if (!hasMatchingItem) return false;
          }
          return true;
      }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [sales, viewMode, filters]);

  const getEODStats = () => {
      const dateStr = selectedDateReport ? selectedDateReport.date : new Date().toISOString().split('T')[0];
      const dayAch = sales.find(s => s.date === dateStr)?.totalValue || 0;
      const d = new Date(dateStr);
      const day = d.getDay();
      const diff = (day + 6) % 7;
      const monday = new Date(d);
      monday.setDate(d.getDate() - diff);
      monday.setHours(0,0,0,0);
      const targetDate = new Date(dateStr);
      targetDate.setHours(23,59,59,999);
      const weekAch = sales.reduce((acc, s) => {
          const sDate = new Date(s.date);
          if (sDate >= monday && sDate <= targetDate) return acc + s.totalValue;
          return acc;
      }, 0);
      return { dateStr, dayAch, weekAch };
  };

  const handleEODShare = () => {
      const { dateStr, dayAch, weekAch } = getEODStats();
      const updatedUser = { ...user, customTargets: { daily: eodForm.dayTarget, weekly: eodForm.weekTarget, eol: eodForm.eolTarget } };
      saveUser(updatedUser);
      onUpdateUser(updatedUser);
      const reportText = generateStoreEODReport(user, dateStr, eodForm.dayTarget, dayAch, eodForm.weekTarget, weekAch, eodForm.eolTarget, eodForm.eolAchieve);
      window.open(`https://wa.me/?text=${encodeURIComponent(reportText)}`, '_blank');
      setShowEODModal(false);
  };

  const handleDeleteEntry = async (date: string) => {
    if (window.confirm('Are you sure?')) {
      await deleteDailyReport(date);
      setSelectedDateReport(null);
      onDataChange();
    }
  };

  const handleRemoveItem = async (report: DailyReport, index: number) => {
      const updatedItems = [...report.items];
      updatedItems.splice(index, 1);
      if (updatedItems.length === 0) {
          await handleDeleteEntry(report.date);
          return;
      }
      const totalQty = updatedItems.reduce((acc, item) => acc + item.quantity, 0);
      const totalValue = updatedItems.reduce((acc, item) => acc + (item.price * item.quantity), 0);
      const updatedReport = { ...report, items: updatedItems, totalQty, totalValue };
      await updateDailyReport(report.date, updatedReport);
      setSelectedDateReport(updatedReport);
      onDataChange();
  };

  const startEditItem = (item: SaleItem, index: number) => { setEditingItemIndex(index); setEditItemState({ ...item }); };
  const saveEditItem = async (report: DailyReport, index: number) => {
      if (!editItemState) return;
      const updatedItems = [...report.items];
      updatedItems[index] = editItemState;
      const totalQty = updatedItems.reduce((acc, item) => acc + item.quantity, 0);
      const totalValue = updatedItems.reduce((acc, item) => acc + (item.price * item.quantity), 0);
      const updatedReport = { ...report, items: updatedItems, totalQty, totalValue };
      await updateDailyReport(report.date, updatedReport);
      setSelectedDateReport(updatedReport);
      setEditingItemIndex(null); setEditItemState(null);
      onDataChange();
  };

  const cancelEdit = () => { setEditingItemIndex(null); setEditItemState(null); };
  const handleRemoveImage = async (report: DailyReport, imgIndex: number) => {
      if(!confirm("Delete this image?")) return;
      const images = report.billImages || (report.billImage ? [report.billImage] : []);
      const updatedImages = images.filter((_, i) => i !== imgIndex);
      const updatedReport = { ...report, billImages: updatedImages, billImage: undefined };
      await updateDailyReport(report.date, updatedReport);
      setSelectedDateReport(updatedReport);
      onDataChange();
  };

  const copyReport = (report: DailyReport) => {
    const text = generateTextReport(user, report);
    navigator.clipboard.writeText(text);
    alert('Report copied!');
  };

  const handleCopyToday = () => {
      const todayStr = new Date().toISOString().split('T')[0];
      const todayReport = sales.find(s => s.date === todayStr);
      if(todayReport) copyReport(todayReport); else alert('No entry found for today.');
  };

  const downloadImage = (base64: string, date: string, index: number) => {
      const a = document.createElement("a"); a.href = base64; a.download = `Bill_${date}_${index + 1}.jpg`; a.click();
  };

  const getReportImages = (report: DailyReport) => { return report.billImages || (report.billImage ? [report.billImage] : []); };

  return (
    <div className="space-y-6">
      <GlassCard className="p-4 bg-gradient-to-r from-zinc-50 to-white dark:from-zinc-900 dark:to-zinc-800 animate-in slide-in-from-top-4 duration-500 border-l-4 border-l-yellow-400 shadow-lg">
         <div className="flex gap-3">
             <div className="bg-yellow-400/20 p-2 rounded-full h-fit"><Quote className="text-yellow-600 dark:text-yellow-400" size={18} fill="currentColor" fillOpacity={0.5} /></div>
             <div><p className="text-sm font-semibold italic text-slate-700 dark:text-slate-200">"{quote}"</p><p className="text-[10px] text-slate-400 mt-1 font-bold uppercase tracking-wider">AI Daily Inspiration</p></div>
         </div>
      </GlassCard>

      <div className="grid grid-cols-3 gap-2">
          <GlassCard className="p-3 flex flex-col items-center justify-center text-center bg-blue-50/50 dark:bg-blue-900/10 animate-in zoom-in duration-500 delay-100 border-blue-100/50 dark:border-blue-500/20"><Target size={20} className="text-blue-500 mb-1" /><p className="text-[10px] uppercase text-slate-500 font-bold">Target</p><p className="text-sm font-bold truncate w-full"><CountUp end={user.monthlyTarget / 1000} prefix="₹" suffix="k" /></p></GlassCard>
          <GlassCard className="p-3 flex flex-col items-center justify-center text-center bg-green-50/50 dark:bg-green-900/10 animate-in zoom-in duration-500 delay-200 border-green-100/50 dark:border-green-500/20"><Trophy size={20} className="text-green-500 mb-1" /><p className="text-[10px] uppercase text-slate-500 font-bold">Achieved</p><p className="text-sm font-bold truncate w-full"><CountUp end={mtdValue} prefix="₹" /></p></GlassCard>
          <GlassCard className="p-3 flex flex-col items-center justify-center text-center bg-orange-50/50 dark:bg-orange-900/10 animate-in zoom-in duration-500 delay-300 border-orange-100/50 dark:border-orange-500/20"><Wallet size={20} className="text-orange-500 mb-1" /><p className="text-[10px] uppercase text-slate-500 font-bold">Balance</p><p className="text-sm font-bold truncate w-full"><CountUp end={balance} prefix="₹" /></p></GlassCard>
      </div>

      <GlassCard className="p-5 animate-in slide-in-from-bottom-4 duration-500">
          <div className="flex justify-between items-end mb-2"><div><h2 className="font-bold text-lg flex items-center gap-2">{monthName}</h2><p className="text-xs text-slate-500">Monthly Progress</p></div><p className="text-2xl font-bold text-zinc-800 dark:text-white"><CountUp end={mtdValue} prefix="₹" /></p></div>
          <div className="h-4 w-full bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden shadow-inner"><div className="h-full bg-black dark:bg-white transition-all duration-1000 ease-out relative" style={{ width: `${mtdPercentage}%` }}><div className="absolute inset-0 bg-white/20 animate-[shine_2s_infinite]" /></div></div>
          <div className="flex justify-between mt-2 text-xs text-slate-500"><span>0%</span><span><CountUp end={mtdPercentage} suffix="%" /></span><span>100%</span></div>
      </GlassCard>

      <div className="flex gap-2"><GlassButton onClick={handleCopyToday} className="flex-1 !py-3 bg-zinc-800 hover:bg-zinc-700 !text-sm"><Copy size={16} /> Copy Report</GlassButton><GlassButton onClick={() => setShowEODModal(true)} className="flex-1 !py-3 bg-indigo-600 hover:bg-indigo-700 !text-sm !border-indigo-400/30 shadow-indigo-500/20"><Store size={16} /> Store EOD</GlassButton></div>
      <div className="flex p-1 bg-white/20 dark:bg-white/10 rounded-xl backdrop-blur-sm w-fit mx-auto"><button onClick={() => setViewMode('calendar')} className={`px-6 py-2 rounded-lg text-sm font-medium transition-all ${viewMode === 'calendar' ? 'bg-white shadow text-black' : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'}`}>Calendar</button><button onClick={() => setViewMode('list')} className={`px-6 py-2 rounded-lg text-sm font-medium transition-all ${viewMode === 'list' ? 'bg-white shadow text-black' : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'}`}>List View</button></div>

      {viewMode === 'calendar' ? (
        <GlassCard className="p-4">
          <div className="flex items-center justify-between mb-4 px-2"><button onClick={prevMonth} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-white/10 transition-colors"><ChevronLeft size={20} className="text-slate-600 dark:text-slate-300" /></button><h3 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2"><CalendarIcon size={18} className="text-blue-500" />{currentMonth.toLocaleString('default', { month: 'long', year: 'numeric' })}</h3><button onClick={nextMonth} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-white/10 transition-colors"><ChevronRight size={20} className="text-slate-600 dark:text-slate-300" /></button></div>
          <div className="grid grid-cols-7 gap-2 mb-2">{['S', 'M', 'T', 'W', 'T', 'F', 'S'].map(d => ( <div key={d} className="text-center text-xs font-bold text-slate-400">{d}</div> ))}</div>
          <div className="grid grid-cols-7 gap-3">
            {calendarDays.map((d, i) => {
              if (!d) return <div key={i} />;
              const report = sales.find(s => s.date === d.dateStr);
              const isToday = d.dateStr === new Date().toISOString().split('T')[0];
              const isWeekOff = report?.isWeekOff;
              return (
                <div key={d.dateStr} onClick={() => report ? setSelectedDateReport(report) : null} style={{ animationDelay: `${i * 0.04}s` }} className={`aspect-square rounded-full flex flex-col items-center justify-center cursor-pointer transition-all border shadow-sm relative overflow-hidden animate-in zoom-in fade-in duration-300 fill-mode-backwards ${isToday ? 'border-zinc-900 dark:border-white ring-2 ring-zinc-200 dark:ring-zinc-700' : 'border-transparent hover:bg-white/20'} ${report ? (isWeekOff ? 'bg-gray-200 dark:bg-gray-800' : 'bg-zinc-100 dark:bg-zinc-800/80') : ''}`}>
                  <span className={`text-xs ${isToday ? 'font-bold text-black dark:text-white' : ''}`}>{d.day}</span>
                  {report && <span className={`text-[9px] font-bold mt-0.5 ${isWeekOff ? 'text-gray-500' : 'text-green-600 dark:text-green-400'}`}>{isWeekOff ? 'OFF' : `${report.totalQty}u`}</span>}
                </div>
              );
            })}
          </div>
        </GlassCard>
      ) : (
        <div className="space-y-4">
          <div className="px-2">
            <button onClick={() => setShowFilters(!showFilters)} className={`flex items-center gap-2 text-sm font-semibold transition-colors ${showFilters ? 'text-black dark:text-white' : 'text-slate-500'}`}><Filter size={16} /> Filters</button>
            {showFilters && (
                <GlassCard className="mt-2 p-4 animate-in slide-in-from-top-2">
                    <div className="space-y-3"><div className="relative"><SearchIcon size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" /><input className="w-full bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-xl pl-9 pr-3 py-2 text-sm outline-none" placeholder="Filter by product name..." value={filters.productName} onChange={e => setFilters({...filters, productName: e.target.value})} /></div><div className="grid grid-cols-3 gap-3"><input type="date" className="bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-xl px-3 py-2 text-sm outline-none" value={filters.date} onChange={e => setFilters({...filters, date: e.target.value})} /><input type="number" placeholder="Min Qty" className="bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-xl px-3 py-2 text-sm outline-none" value={filters.minQty} onChange={e => setFilters({...filters, minQty: e.target.value})} /><input type="number" placeholder="Min Price" className="bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-xl px-3 py-2 text-sm outline-none" value={filters.minPrice} onChange={e => setFilters({...filters, minPrice: e.target.value})} /></div><div className="flex justify-end pt-2"><button onClick={() => setFilters({ productName: '', date: '', minQty: '', minPrice: '' })} className="text-xs text-red-500 font-bold hover:underline">Clear All</button></div></div>
                </GlassCard>
            )}
          </div>
          {[...filteredSales].map((report, i) => (
             <GlassCard key={report.date} className="p-4 animate-in slide-in-from-bottom-4 duration-500" onClick={() => setSelectedDateReport(report)} style={{ animationDelay: `${i * 0.05}s` }}>
                <div className="flex justify-between items-center"><div><p className="font-bold flex items-center gap-2 text-zinc-900 dark:text-zinc-100">{formatToDisplayDate(report.date)}{report.isWeekOff && <span className="text-[10px] bg-gray-200 text-gray-600 px-2 py-0.5 rounded-full">OFF</span>}</p><p className="text-sm text-slate-500">{report.isWeekOff ? 'Week Off' : `${report.totalQty} items • ₹${report.totalValue.toLocaleString()}`}</p></div><div className="h-8 w-8 bg-zinc-100 dark:bg-zinc-800 rounded-full flex items-center justify-center text-black dark:text-white"><List size={16} /></div></div>
             </GlassCard>
          ))}
          {filteredSales.length === 0 && <div className="text-center py-10 opacity-60"><Filter size={32} className="mx-auto mb-2 text-slate-400" /><p className="text-slate-500 text-sm">No matching records found.</p></div>}
        </div>
      )}

      <Modal isOpen={!!selectedDateReport} onClose={() => { setSelectedDateReport(null); cancelEdit(); }} title={selectedDateReport ? formatToDisplayDate(selectedDateReport.date) : ''}>
        {selectedDateReport && (
          <div className="space-y-6 pb-4">
            {selectedDateReport.isWeekOff ? ( <div className="text-center py-8 bg-gray-50 dark:bg-white/5 rounded-2xl border border-dashed border-gray-300"><Ban size={40} className="mx-auto text-gray-400 mb-2" /><p className="text-gray-500 font-medium">Marked as Week Off</p></div> ) : (
                <>
                <div className="grid grid-cols-2 gap-4"><div className="bg-blue-50 dark:bg-blue-900/30 p-3 rounded-lg text-center"><p className="text-xs text-slate-500">Value</p><p className="font-bold text-blue-600">₹{selectedDateReport.totalValue.toLocaleString()}</p></div><div className="bg-purple-50 dark:bg-purple-900/30 p-3 rounded-lg text-center"><p className="text-xs text-slate-500">Quantity</p><p className="font-bold text-purple-600">{selectedDateReport.totalQty}</p></div></div>
                <div className="space-y-3"><h4 className="text-sm font-semibold text-slate-500 uppercase tracking-wider sticky top-0 bg-white/95 dark:bg-zinc-900 backdrop-blur py-2 z-10">Items Sold</h4>
                    {selectedDateReport.items.map((item, idx) => {
                        const isEditing = editingItemIndex === idx;
                        return (
                        <div key={idx} className={`flex justify-between items-center p-3 rounded-lg border transition-all ${isEditing ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-200' : 'bg-white/40 dark:bg-white/5 border-white/10'}`}>
                            {isEditing && editItemState ? (
                                <div className="w-full space-y-2"><input className="w-full bg-transparent border-b border-blue-300 text-sm font-medium focus:outline-none" value={editItemState.productName} onChange={(e) => setEditItemState({...editItemState, productName: e.target.value})} placeholder="Product Name" /><div className="flex gap-2"><div className="flex-1"><label className="text-[9px] uppercase text-slate-500 font-bold">Qty</label><input type="number" className="w-full bg-transparent border-b border-blue-300 text-sm focus:outline-none" value={editItemState.quantity} onChange={(e) => setEditItemState({...editItemState, quantity: parseInt(e.target.value) || 0})} /></div><div className="flex-1"><label className="text-[9px] uppercase text-slate-500 font-bold">Unit Price</label><input type="number" className="w-full bg-transparent border-b border-blue-300 text-sm focus:outline-none" value={editItemState.price} onChange={(e) => setEditItemState({...editItemState, price: parseFloat(e.target.value) || 0})} /></div></div><div className="flex justify-end gap-2 mt-2"><button onClick={cancelEdit} className="p-1 rounded-full bg-gray-200 text-gray-600"><X size={14} /></button><button onClick={() => saveEditItem(selectedDateReport, idx)} className="p-1 rounded-full bg-green-500 text-white"><Check size={14} /></button></div></div>
                            ) : (
                                <><div><p className="font-medium text-sm">{item.productName}</p><p className="text-xs text-slate-500">₹{item.price} x {item.quantity}</p></div><div className="flex items-center gap-2"><p className="font-bold text-sm mr-2">₹{item.price * item.quantity}</p><button onClick={() => startEditItem(item, idx)} className="text-blue-400 hover:text-blue-600 p-1"><Pencil size={14} /></button><button onClick={() => handleRemoveItem(selectedDateReport, idx)} className="text-red-400 hover:text-red-600 p-1"><Trash2 size={14} /></button></div></>
                            )}
                        </div>
                    )})}
                </div>
                {getReportImages(selectedDateReport).length > 0 && (
                    <div className="mt-4"><h4 className="text-sm font-semibold text-slate-500 mb-2 sticky top-0 bg-white/95 dark:bg-zinc-900 backdrop-blur py-2 z-10">Bill Copies ({getReportImages(selectedDateReport).length})</h4><div className="grid grid-cols-2 gap-3">
                            {getReportImages(selectedDateReport).map((img, idx) => (
                                <div key={idx} className="report-img-inner-shadow relative group rounded-xl overflow-hidden border border-white/20 aspect-square shadow-lg"><img src={img} alt="Bill" className="w-full h-full object-cover" /><div className="absolute inset-0 bg-black/40 flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity gap-2 z-10"><div className="flex gap-2"><button onClick={() => setZoomedImage(img)} className="p-2 bg-white rounded-full text-black hover:bg-gray-100"><Maximize2 size={16} /></button><button onClick={() => downloadImage(img, selectedDateReport.date, idx)} className="p-2 bg-white rounded-full text-black hover:bg-gray-100"><Download size={16} /></button></div><button onClick={() => handleRemoveImage(selectedDateReport, idx)} className="px-3 py-1 bg-red-500 text-white text-xs rounded-full hover:bg-red-600 mt-2">Delete</button></div></div>
                            ))}
                        </div></div>
                )}
                </>
            )}
             <div className="grid grid-cols-2 gap-3 mt-6 sticky bottom-0 bg-white/0 pt-2"><GlassButton onClick={() => copyReport(selectedDateReport)} variant="primary">Copy Report</GlassButton><GlassButton variant="danger" onClick={() => handleDeleteEntry(selectedDateReport.date)}>Delete All</GlassButton></div>
          </div>
        )}
      </Modal>

      <Modal isOpen={showEODModal} onClose={() => setShowEODModal(false)} title="Store EOD Report">
        <div className="space-y-4">
            <div className="bg-blue-50 dark:bg-blue-900/20 p-3 rounded-xl mb-4"><p className="text-xs text-blue-600 dark:text-blue-300 font-semibold mb-1">Date: {formatToDisplayDate(getEODStats().dateStr)}</p><p className="text-xs text-slate-500">Calculated stats are based on today's entries.</p></div>
            <div className="grid grid-cols-2 gap-4"><div className="space-y-1"><label className="text-[10px] font-bold uppercase text-slate-500">Day Target</label><GlassInput type="number" value={eodForm.dayTarget} onChange={e => setEodForm({...eodForm, dayTarget: parseInt(e.target.value) || 0})} /></div><div className="space-y-1"><label className="text-[10px] font-bold uppercase text-slate-500">Day Achieved</label><div className="px-3 py-3 rounded-xl bg-gray-100 dark:bg-white/5 border border-transparent font-bold text-slate-700 dark:text-slate-300">₹{getEODStats().dayAch.toLocaleString()}</div></div><div className="space-y-1"><label className="text-[10px] font-bold uppercase text-slate-500">Week Target</label><GlassInput type="number" value={eodForm.weekTarget} onChange={e => setEodForm({...eodForm, weekTarget: parseInt(e.target.value) || 0})} /></div><div className="space-y-1"><label className="text-[10px] font-bold uppercase text-slate-500">Week Achieved</label><div className="px-3 py-3 rounded-xl bg-gray-100 dark:bg-white/5 border border-transparent font-bold text-slate-700 dark:text-slate-300">₹{getEODStats().weekAch.toLocaleString()}</div></div><div className="space-y-1"><label className="text-[10px] font-bold uppercase text-slate-500">EOL Target</label><GlassInput type="number" value={eodForm.eolTarget} onChange={e => setEodForm({...eodForm, eolTarget: parseInt(e.target.value) || 0})} /></div><div className="space-y-1"><label className="text-[10px] font-bold uppercase text-slate-500">EOL Achieved</label><GlassInput type="number" value={eodForm.eolAchieve} onChange={e => setEodForm({...eodForm, eolAchieve: parseInt(e.target.value) || 0})} /></div></div>
            <GlassButton onClick={handleEODShare} className="w-full mt-4 flex items-center justify-center gap-2"><Send size={18} /> Share to WhatsApp</GlassButton>
        </div>
      </Modal>

      {zoomedImage && (
          <div className="fixed inset-0 z-[60] bg-black/95 backdrop-blur-xl flex items-center justify-center p-2"><button onClick={() => setZoomedImage(null)} className="absolute top-4 right-4 p-3 bg-white/10 rounded-full text-white hover:bg-white/20 z-50"><X size={24} /></button><img src={zoomedImage} className="max-w-full max-h-[90vh] object-contain shadow-2xl rounded-lg" alt="Zoomed Bill" /></div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { Send, Target, TrendingUp, Calendar, Copy, Check, ChevronLeft, ChevronRight, List, Calendar as CalendarIcon, Trash2, X, AlertCircle, Trophy, Wallet } from 'lucide-react';
import { GlassCard, GlassInput, GlassButton, Modal } from './ui/GlassComponents';
import { UserProfile, StoreEODEntry } from '../types';
import { saveUser, getEODEntries, saveEODEntry, deleteEODEntry } from '../services/storageService';
import { generateStoreEODReport, formatToDisplayDate } from '../services/reportService';

const CountUp = ({ end, prefix = '', suffix = '', duration = 1000 }: { end: number, prefix?: string, suffix?: string, duration?: number }) => {
    const [count, setCount] = useState(0);
    useEffect(() => {
        let startTime: number;
        let animationFrame: number;
        const animate = (time: number) => {
            if (!startTime) startTime = time;
            const progress = Math.min((time - startTime) / duration, 1);
            const easeValue = 1 - Math.pow(1 - progress, 3);
            setCount(Math.floor(end * easeValue));
            if (progress < 1) animationFrame = requestAnimationFrame(animate);
        };
        animationFrame = requestAnimationFrame(animate);
        return () => cancelAnimationFrame(animationFrame);
    }, [end, duration]);
    return <span>{prefix}{count.toLocaleString()}{suffix}</span>;
};

const EOD: React.FC<EODProps> = ({ user, onUpdateUser }) => {
    const [viewMode, setViewMode] = useState<'entry' | 'calendar'>('entry');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [achievement, setAchievement] = useState<number>(0);
    const [eolAchieve, setEolAchieve] = useState<number>(0);
    const [showSuccess, setShowSuccess] = useState(false);
    const [eodHistory, setEodHistory] = useState<StoreEODEntry[]>([]);

    const [weeklyTarget, setWeeklyTarget] = useState(user.customTargets?.weekly || 0);
    const [eolTarget, setEolTarget] = useState(user.customTargets?.eol || 0);
    const [currentMonth, setCurrentMonth] = useState(new Date());

    const refreshHistory = async () => {
      const entries = await getEODEntries();
      setEodHistory(entries);
    };

    useEffect(() => { refreshHistory(); }, []);

    useEffect(() => {
        const entry = eodHistory.find(e => e.date === date);
        if (entry) {
            setAchievement(entry.achievement);
            setEolAchieve(entry.eolAchieve);
            setWeeklyTarget(entry.weekTarget);
            setEolTarget(entry.eolTarget);
        } else {
            setAchievement(0);
            setEolAchieve(0);
        }
    }, [date, eodHistory]);

    const dailyTarget = Math.round(weeklyTarget / 7);

    const calculateWeeklyAch = (targetDate: string) => {
        const d = new Date(targetDate);
        const day = d.getDay();
        const diff = (day + 6) % 7; 
        const monday = new Date(d);
        monday.setDate(d.getDate() - diff);
        monday.setHours(0,0,0,0);
        const mondayStr = monday.toISOString().split('T')[0];
        let total = eodHistory.reduce((acc, entry) => {
            if (entry.date >= mondayStr && entry.date <= targetDate) {
                if (entry.date === date) return acc;
                return acc + entry.achievement;
            }
            return acc;
        }, 0);
        total += achievement;
        return total;
    };

    const handleShare = async () => {
        const entry: StoreEODEntry = { date, achievement, eolAchieve, dayTarget: dailyTarget, weekTarget: weeklyTarget, eolTarget: eolTarget };
        await saveEODEntry(entry);
        const updatedUser = { ...user, customTargets: { weekly: weeklyTarget, daily: dailyTarget, eol: eolTarget } };
        saveUser(updatedUser);
        onUpdateUser(updatedUser);
        await refreshHistory();
        const weekAch = calculateWeeklyAch(date);
        const reportText = generateStoreEODReport(user, date, dailyTarget, achievement, weeklyTarget, weekAch, eolTarget, eolAchieve);
        window.open(`https://wa.me/?text=${encodeURIComponent(reportText)}`, '_blank');
        setShowSuccess(true);
    };

    const handleDelete = async (d: string) => {
        if (confirm("Delete this EOD record?")) {
            await deleteEODEntry(d);
            await refreshHistory();
        }
    };

    const calendarDays = useMemo(() => {
        const year = currentMonth.getFullYear();
        const month = currentMonth.getMonth();
        const daysInMonth = new Date(year, month + 1, 0).getDate();
        const firstDay = new Date(year, month, 1).getDay();
        const days = [];
        for (let i = 0; i < firstDay; i++) days.push(null);
        for (let i = 1; i <= daysInMonth; i++) {
            const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
            days.push({ day: i, dateStr });
        }
        return days;
    }, [currentMonth]);

    const weekAchTotal = useMemo(() => calculateWeeklyAch(date), [date, achievement, eodHistory]);
    const weeklyRemaining = Math.max(0, weeklyTarget - weekAchTotal);
    const weeklyProgress = weeklyTarget > 0 ? Math.min((weekAchTotal / weeklyTarget) * 100, 100) : 0;

    return (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="text-center animate-reveal"><h2 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-purple-600">Store Performance</h2><p className="text-slate-500 text-sm">Weekly Target Tracking</p></div>
            <div className="grid grid-cols-3 gap-2 animate-reveal" style={{ animationDelay: '100ms' }}>
                <GlassCard className="p-3 flex flex-col items-center justify-center text-center bg-blue-50/50 dark:bg-blue-900/10 border-blue-100/50 dark:border-blue-500/20"><Target size={20} className="text-blue-500 mb-1" /><p className="text-[10px] uppercase text-slate-500 font-bold">Week Target</p><p className="text-sm font-bold truncate w-full"><CountUp end={weeklyTarget} prefix="₹" /></p></GlassCard>
                <GlassCard className="p-3 flex flex-col items-center justify-center text-center bg-green-50/50 dark:bg-green-900/10 border-green-100/50 dark:border-green-500/20"><Trophy size={20} className="text-green-500 mb-1" /><p className="text-[10px] uppercase text-slate-500 font-bold">Achieved</p><p className="text-sm font-bold truncate w-full"><CountUp end={weekAchTotal} prefix="₹" /></p></GlassCard>
                <GlassCard className="p-3 flex flex-col items-center justify-center text-center bg-orange-50/50 dark:bg-orange-900/10 border-orange-100/50 dark:border-orange-500/20"><Wallet size={20} className="text-orange-500 mb-1" /><p className="text-[10px] uppercase text-slate-500 font-bold">Remaining</p><p className="text-sm font-bold truncate w-full"><CountUp end={weeklyRemaining} prefix="₹" /></p></GlassCard>
            </div>
            <GlassCard className="p-4 animate-reveal" style={{ animationDelay: '150ms' }}><div className="flex justify-between text-[11px] font-bold uppercase text-slate-400 mb-2"><span>Weekly Goal Progress</span><span className={weeklyProgress >= 100 ? 'text-green-500' : ''}><CountUp end={weeklyProgress} suffix="%" /></span></div><div className="h-3 w-full bg-slate-100 dark:bg-zinc-800 rounded-full overflow-hidden p-0.5 shadow-inner"><div className={`h-full rounded-full transition-all duration-1000 ease-out relative ${weeklyProgress >= 100 ? 'bg-gradient-to-r from-green-400 to-emerald-600' : 'bg-gradient-to-r from-indigo-500 to-blue-600'}`} style={{ width: `${weeklyProgress}%` }}><div className="absolute inset-0 bg-white/20 animate-shine" /></div></div></GlassCard>
            <div className="flex p-1 bg-white/40 dark:bg-white/10 rounded-xl backdrop-blur-sm w-fit mx-auto border border-white/20 animate-reveal" style={{ animationDelay: '200ms' }}><button onClick={() => setViewMode('entry')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all duration-300 ${viewMode === 'entry' ? 'bg-black text-white shadow-lg scale-105' : 'text-slate-500 hover:text-slate-700 dark:text-slate-400 hover:bg-black/5'}`}>Manual Entry</button><button onClick={() => setViewMode('calendar')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all duration-300 ${viewMode === 'calendar' ? 'bg-black text-white shadow-lg scale-105' : 'text-slate-500 hover:text-slate-700 dark:text-slate-400 hover:bg-black/5'}`}>History View</button></div>
            {viewMode === 'entry' ? (
                <div className="space-y-6">
                    <GlassCard className="p-5 space-y-5 shadow-xl animate-reveal" style={{ animationDelay: '300ms' }}><div className="flex items-center gap-3 border-b border-gray-100 dark:border-white/10 pb-3 relative"><div className="p-2 bg-blue-500/10 rounded-lg text-blue-500"><CalendarIcon size={20} /></div><div className="flex-1 relative"><span className="absolute inset-0 flex items-center font-bold text-lg pointer-events-none text-slate-800 dark:text-white">{formatToDisplayDate(date)}</span><input type="date" value={date} onChange={e => setDate(e.target.value)} className="opacity-0 absolute inset-0 w-full h-full cursor-pointer" /></div><ChevronRight size={16} className="text-slate-400 transform rotate-90" /></div><div className="grid grid-cols-1 gap-6"><div className="space-y-2 group"><label className="text-[11px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2"><Target size={14} className="text-blue-500" /> Weekly Store Target (₹)</label><GlassInput type="number" placeholder="Set this week's goal" value={weeklyTarget || ''} onChange={e => setWeeklyTarget(parseInt(e.target.value) || 0)} className="font-mono text-lg" /><p className="text-[10px] text-slate-400 italic">Target applies to Mon - Sun cycle</p></div><div className="space-y-2 group"><label className="text-[11px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2"><TrendingUp size={14} className="text-green-500" /> Today Achievement (₹)</label><GlassInput type="number" placeholder="Enter today's total" value={achievement || ''} onChange={e => setAchievement(parseInt(e.target.value) || 0)} className="border-green-200 dark:border-green-500/30 font-bold text-2xl font-mono text-green-700 dark:text-green-400 h-14" /></div></div></GlassCard>
                    <GlassCard className="p-5 space-y-4 animate-reveal" style={{ animationDelay: '400ms' }}><div className="flex items-center justify-between mb-2"><h3 className="font-bold text-sm text-slate-500 uppercase tracking-widest">EOL REPORT</h3><span className="text-[10px] bg-zinc-100 dark:bg-zinc-800 px-2 py-0.5 rounded text-slate-400">Optional</span></div><div className="grid grid-cols-2 gap-4"><div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">Target</label><GlassInput type="number" value={eolTarget || ''} onChange={e => setEolTarget(parseInt(e.target.value) || 0)} placeholder="0" className="h-10 text-sm" /></div><div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">Achieved</label><GlassInput type="number" value={eolAchieve || ''} onChange={e => setEolAchieve(parseInt(e.target.value) || 0)} placeholder="0" className="h-10 text-sm" /></div></div></GlassCard>
                    <GlassButton onClick={handleShare} className="w-full py-4 text-lg animate-reveal" style={{ animationDelay: '500ms' }}><Send size={20} /> Generate & Share Report</GlassButton>
                </div>
            ) : (
                <GlassCard className="p-4 space-y-6 animate-reveal overflow-hidden" style={{ animationDelay: '300ms' }}><div className="flex items-center justify-between px-2"><button onClick={() => setCurrentMonth(new Date(currentMonth.setMonth(currentMonth.getMonth()-1)))} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-white/10 transition-colors"><ChevronLeft size={20} /></button><h3 className="font-bold text-lg">{currentMonth.toLocaleString('default', { month: 'long', year: 'numeric' })}</h3><button onClick={() => setCurrentMonth(new Date(currentMonth.setMonth(currentMonth.getMonth()+1)))} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-white/10 transition-colors"><ChevronRight size={20} /></button></div><div className="grid grid-cols-7 gap-2">{['S', 'M', 'T', 'W', 'T', 'F', 'S'].map(d => ( <div key={d} className="text-center text-[10px] font-bold text-slate-400 uppercase opacity-50">{d}</div> ))}{calendarDays.map((d, i) => { if (!d) return <div key={i} />; const entry = eodHistory.find(e => e.date === d.dateStr); const isToday = d.dateStr === new Date().toISOString().split('T')[0]; const isAchieved = entry && entry.achievement >= entry.dayTarget; return ( <div key={d.dateStr} onClick={() => { setDate(d.dateStr); setViewMode('entry'); }} style={{ animationDelay: `${i * 15}ms` }} className={`aspect-square rounded-xl border flex flex-col items-center justify-center cursor-pointer transition-all duration-300 relative animate-in zoom-in-90 fade-in fill-mode-backwards ${isToday ? 'border-blue-500 ring-2 ring-blue-100 dark:ring-blue-900/30 scale-105 z-10' : 'border-transparent hover:bg-slate-50 dark:hover:bg-white/5 hover:scale-110'} ${entry ? 'bg-white dark:bg-zinc-800 shadow-sm border-gray-100 dark:border-white/5' : 'bg-transparent'}`}> <span className={`text-xs ${isToday ? 'font-black text-blue-600' : 'text-slate-500'}`}>{d.day}</span> {entry && ( <div className={`w-1.5 h-1.5 rounded-full mt-1 ${isAchieved ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]' : 'bg-blue-400'}`} /> )} </div> ); })}</div><div className="space-y-3 pt-4 border-t border-gray-100 dark:border-white/5"><h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest px-1">Weekly History</h4><div className="space-y-3">{eodHistory.filter(e => e.date.startsWith(currentMonth.toISOString().slice(0, 7))).sort((a,b) => b.date.localeCompare(a.date)).map((entry, idx) => ( <div key={entry.date} style={{ animationDelay: `${idx * 100}ms` }} className="flex justify-between items-center p-3 bg-white/40 dark:bg-white/5 rounded-xl border border-white/20 hover:border-blue-400/50 transition-all group animate-in slide-in-from-right-4 fade-in fill-mode-backwards"> <div><p className="text-sm font-bold">{formatToDisplayDate(entry.date)}</p><p className="text-[10px] text-slate-500">Achieved: ₹<CountUp end={entry.achievement} /></p></div><div className="flex items-center gap-4"><div className={`px-2 py-0.5 rounded text-[10px] font-bold ${entry.achievement >= entry.dayTarget ? 'bg-green-100 text-green-600' : 'bg-blue-100 text-blue-600'}`}>{Math.round((entry.achievement / entry.dayTarget) * 100)}%</div><button onClick={(e) => { e.stopPropagation(); handleDelete(entry.date); }} className="text-red-400 hover:text-red-600 p-1 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"><Trash2 size={16} /></button></div></div> ))}</div></div></GlassCard>
            )}
            <Modal isOpen={showSuccess} onClose={() => setShowSuccess(false)} title="Report Generated">
                <div className="text-center space-y-6 pt-4 animate-reveal"><div className="relative w-20 h-20 mx-auto"><div className="absolute inset-0 bg-green-500/20 rounded-full animate-pulse-slow scale-150" /><div className="relative w-20 h-20 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center text-green-600 shadow-inner"><Check size={40} className="animate-in zoom-in duration-500" strokeWidth={3} /></div></div><div><p className="text-lg font-bold">Entry Saved!</p><p className="text-sm text-slate-500 mt-1">EOD totals for {formatToDisplayDate(date)} have been recorded.</p></div><GlassButton onClick={() => setShowSuccess(false)} variant="secondary" className="w-full border-green-200">Continue</GlassButton></div>
            </Modal>
        </div>
    );
};

