      <div className="flex p-1 bg-white/20 dark:bg-white/10 rounded-xl backdrop-blur-sm w-fit mx-auto"><button onClick={() => setViewMode('calendar')} className={`px-6 py-2 rounded-lg text-sm font-medium transition-all ${viewMode === 'calendar' ? 'bg-white shadow text-black' : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'}`}>Calendar</button><button onClick={() => setViewMode('list')} className={`px-6 py-2 rounded-lg text-sm font-medium transition-all ${viewMode === 'list' ? 'bg-white shadow text-black' : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'}`}>List View</button></div>

      {viewMode === 'calendar' ? (
