                </div>
                {getReportImages(selectedDateReport).length > 0 && (
                    <div className="mt-4"><h4 className="text-sm font-semibold text-slate-500 mb-2 sticky top-0 bg-white/95 dark:bg-zinc-900 backdrop-blur py-2 z-10">Bill Copies ({getReportImages(selectedDateReport).length})</h4><div className="grid grid-cols-2 gap-3">
                            {getReportImages(selectedDateReport).map((img, idx) => (
                                <div key={idx} className="report-img-inner-shadow relative group rounded-xl overflow-hidden border border-white/20 aspect-square shadow-lg"><img src={img} alt="Bill" className="w-full h-full object-cover" /><div className="absolute inset-0 bg-black/40 flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity gap-2 z-10"><div className="flex gap-2"><button onClick={() => setZoomedImage(img)} className="p-2 bg-white rounded-full text-black hover:bg-gray-100"><Maximize2 size={16} /></button><button onClick={() => downloadImage(img, selectedDateReport.date, idx)} className="p-2 bg-white rounded-full text-black hover:bg-gray-100"><Download size={16} /></button></div><button onClick={() => handleRemoveImage(selectedDateReport, idx)} className="px-3 py-1 bg-red-500 text-white text-xs rounded-full hover:bg-red-600 mt-2">Delete</button></div></div>
                            ))}
                        </div></div>
                )}
                </>
            )}
             <div className="grid grid-cols-2 gap-3 mt-6 sticky bottom-0 bg-white/0 pt-2"><GlassButton onClick={() => copyReport(selectedDateReport)} variant="primary">Copy Report</GlassButton><GlassButton variant="danger" onClick={() => handleDeleteEntry(selectedDateReport.date)}>Delete All</GlassButton></div>
          </div>
        )}
      </Modal>

      <Modal isOpen={showEODModal} onClose={() => setShowEODModal(false)} title="Store EOD Report">
        <div className="space-y-4">
            <div className="bg-blue-50 dark:bg-blue-900/20 p-3 rounded-xl mb-4"><p className="text-xs text-blue-600 dark:text-blue-300 font-semibold mb-1">Date: {formatToDisplayDate(getEODStats().dateStr)}</p><p className="text-xs text-slate-500">Calculated stats are based on today's entries.</p></div>
            <div className="grid grid-cols-2 gap-4"><div className="space-y-1"><label className="text-[10px] font-bold uppercase text-slate-500">Day Target</label><GlassInput type="number" value={eodForm.dayTarget} onChange={e => setEodForm({...eodForm, dayTarget: parseInt(e.target.value) || 0})} /></div><div className="space-y-1"><label className="text-[10px] font-bold uppercase text-slate-500">Day Achieved</label><div className="px-3 py-3 rounded-xl bg-gray-100 dark:bg-white/5 border border-transparent font-bold text-slate-700 dark:text-slate-300">₹{getEODStats().dayAch.toLocaleString()}</div></div><div className="space-y-1"><label className="text-[10px] font-bold uppercase text-slate-500">Week Target</label><GlassInput type="number" value={eodForm.weekTarget} onChange={e => setEodForm({...eodForm, weekTarget: parseInt(e.target.value) || 0})} /></div><div className="space-y-1"><label className="text-[10px] font-bold uppercase text-slate-500">Week Achieved</label><div className="px-3 py-3 rounded-xl bg-gray-100 dark:bg-white/5 border border-transparent font-bold text-slate-700 dark:text-slate-300">₹{getEODStats().weekAch.toLocaleString()}</div></div><div className="space-y-1"><label className="text-[10px] font-bold uppercase text-slate-500">EOL Target</label><GlassInput type="number" value={eodForm.eolTarget} onChange={e => setEodForm({...eodForm, eolTarget: parseInt(e.target.value) || 0})} /></div><div className="space-y-1"><label className="text-[10px] font-bold uppercase text-slate-500">EOL Achieved</label><GlassInput type="number" value={eodForm.eolAchieve} onChange={e => setEodForm({...eodForm, eolAchieve: parseInt(e.target.value) || 0})} /></div></div>
            <GlassButton onClick={handleEODShare} className="w-full mt-4 flex items-center justify-center gap-2"><Send size={18} /> Share to WhatsApp</GlassButton>
        </div>
      </Modal>

      {zoomedImage && (
          <div className="fixed inset-0 z-[60] bg-black/95 backdrop-blur-xl flex items-center justify-center p-2"><button onClick={() => setZoomedImage(null)} className="absolute top-4 right-4 p-3 bg-white/10 rounded-full text-white hover:bg-white/20 z-50"><X size={24} /></button><img src={zoomedImage} className="max-w-full max-h-[90vh] object-contain shadow-2xl rounded-lg" alt="Zoomed Bill" /></div>
      )}
    </div>
  );
};

