import React, { useState, useMemo, useEffect } from 'react';
import { Send, Target, TrendingUp, Calendar, Copy, Check, ChevronLeft, ChevronRight, List, Calendar as CalendarIcon, Trash2, X, AlertCircle, Trophy, Wallet } from 'lucide-react';
import { GlassCard, GlassInput, GlassButton, Modal } from './ui/GlassComponents';
import { UserProfile, StoreEODEntry } from '../types';
import { saveUser, getEODEntries, saveEODEntry, deleteEODEntry } from '../services/storageService';
import { generateStoreEODReport, formatToDisplayDate } from '../services/reportService';

// Fix: Added missing EODProps interface
interface EODProps {
  user: UserProfile;
  onUpdateUser: (u: UserProfile) => void;
}

const CountUp = ({ end, prefix = '', suffix = '', duration = 1000 }: { end: number, prefix?: string, suffix?: string, duration?: number }) => {
    const [count, setCount] = useState(0);
    useEffect(() => {
        let startTime: number;
        let animationFrame: number;
        const animate = (time: number) => {
            if (!startTime) startTime = time;
            const progress = Math.min((time - startTime) / duration, 1);
            const easeValue = 1 - Math.pow(1 - progress, 3);
            setCount(Math.floor(end * easeValue));
            if (progress < 1) animationFrame = requestAnimationFrame(animate);
        };
        animationFrame = requestAnimationFrame(animate);
        return () => cancelAnimationFrame(animationFrame);
    }, [end, duration]);
    return <span>{prefix}{count.toLocaleString()}{suffix}</span>;
};

const EOD: React.FC<EODProps> = ({ user, onUpdateUser }) => {
    const [viewMode, setViewMode] = useState<'entry' | 'calendar'>('entry');
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [achievement, setAchievement] = useState<number>(0);
    const [eolAchieve, setEolAchieve] = useState<number>(0);
    const [showSuccess, setShowSuccess] = useState(false);
    const [eodHistory, setEodHistory] = useState<StoreEODEntry[]>([]);

    const [weeklyTarget, setWeeklyTarget] = useState(user.customTargets?.weekly || 0);
    const [eolTarget, setEolTarget] = useState(user.customTargets?.eol || 0);
    const [currentMonth, setCurrentMonth] = useState(new Date());

    const refreshHistory = async () => {
      const entries = await getEODEntries();
      setEodHistory(entries);
    };

    useEffect(() => { refreshHistory(); }, []);

    useEffect(() => {
        const entry = eodHistory.find(e => e.date === date);
        if (entry) {
            setAchievement(entry.achievement);
            setEolAchieve(entry.eolAchieve);
            setWeeklyTarget(entry.weekTarget);
            setEolTarget(entry.eolTarget);
        } else {
            setAchievement(0);
            setEolAchieve(0);
        }
    }, [date, eodHistory]);

    const dailyTarget = Math.round(weeklyTarget / 7);

    const calculateWeeklyAch = (targetDate: string) => {
        const d = new Date(targetDate);
        const day = d.getDay();
        const diff = (day + 6) % 7; 
        const monday = new Date(d);
        monday.setDate(d.getDate() - diff);
        monday.setHours(0,0,0,0);
        const mondayStr = monday.toISOString().split('T')[0];
        let total = eodHistory.reduce((acc, entry) => {
            if (entry.date >= mondayStr && entry.date <= targetDate) {
                if (entry.date === date) return acc;
                return acc + entry.achievement;
            }
            return acc;
        }, 0);
        total += achievement;
        return total;
    };

    const handleShare = async () => {
        const entry: StoreEODEntry = { date, achievement, eolAchieve, dayTarget: dailyTarget, weekTarget: weeklyTarget, eolTarget: eolTarget };
        await saveEODEntry(entry);
        const updatedUser = { ...user, customTargets: { weekly: weeklyTarget, daily: dailyTarget, eol: eolTarget } };
        saveUser(updatedUser);
        onUpdateUser(updatedUser);
        await refreshHistory();
        const weekAch = calculateWeeklyAch(date);
        const reportText = generateStoreEODReport(user, date, dailyTarget, achievement, weeklyTarget, weekAch, eolTarget, eolAchieve);
        window.open(`https://wa.me/?text=${encodeURIComponent(reportText)}`, '_blank');
        setShowSuccess(true);
    };

    const handleDelete = async (d: string) => {
        if (confirm("Delete this EOD record?")) {
            await deleteEODEntry(d);
            await refreshHistory();
        }
    };

    const calendarDays = useMemo(() => {
        const year = currentMonth.getFullYear();
        const month = currentMonth.getMonth();
        const daysInMonth = new Date(year, month + 1, 0).getDate();
        const firstDay = new Date(year, month, 1).getDay();
        const days = [];
        for (let i = 0; i < firstDay; i++) days.push(null);
        for (let i = 1; i <= daysInMonth; i++) {
            const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
            days.push({ day: i, dateStr });
        }
        return days;
    }, [currentMonth]);

    const weekAchTotal = useMemo(() => calculateWeeklyAch(date), [date, achievement, eodHistory]);
    const weeklyRemaining = Math.max(0, weeklyTarget - weekAchTotal);
    const weeklyProgress = weeklyTarget > 0 ? Math.min((weekAchTotal / weeklyTarget) * 100, 100) : 0;

    return (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="text-center animate-reveal"><h2 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-purple-600">Store Performance</h2><p className="text-slate-500 text-sm">Weekly Target Tracking</p></div>
            <div className="grid grid-cols-3 gap-2 animate-reveal" style={{ animationDelay: '100ms' }}>
                <GlassCard className="p-3 flex flex-col items-center justify-center text-center bg-blue-50/50 dark:bg-blue-900/10 border-blue-100/50 dark:border-blue-500/20"><Target size={20} className="text-blue-500 mb-1" /><p className="text-[10px] uppercase text-slate-500 font-bold">Week Target</p><p className="text-sm font-bold truncate w-full"><CountUp end={weeklyTarget} prefix="₹" /></p></GlassCard>
                <GlassCard className="p-3 flex flex-col items-center justify-center text-center bg-green-50/50 dark:bg-green-900/10 border-green-100/50 dark:border-green-500/20"><Trophy size={20} className="text-green-500 mb-1" /><p className="text-[10px] uppercase text-slate-500 font-bold">Achieved</p><p className="text-sm font-bold truncate w-full"><CountUp end={weekAchTotal} prefix="₹" /></p></GlassCard>
                <GlassCard className="p-3 flex flex-col items-center justify-center text-center bg-orange-50/50 dark:bg-orange-900/10 border-orange-100/50 dark:border-orange-500/20"><Wallet size={20} className="text-orange-500 mb-1" /><p className="text-[10px] uppercase text-slate-500 font-bold">Remaining</p><p className="text-sm font-bold truncate w-full"><CountUp end={weeklyRemaining} prefix="₹" /></p></GlassCard>
            </div>
            <GlassCard className="p-4 animate-reveal" style={{ animationDelay: '150ms' }}><div className="flex justify-between text-[11px] font-bold uppercase text-slate-400 mb-2"><span>Weekly Goal Progress</span><span className={weeklyProgress >= 100 ? 'text-green-500' : ''}><CountUp end={weeklyProgress} suffix="%" /></span></div><div className="h-3 w-full bg-slate-100 dark:bg-zinc-800 rounded-full overflow-hidden p-0.5 shadow-inner"><div className={`h-full rounded-full transition-all duration-1000 ease-out relative ${weeklyProgress >= 100 ? 'bg-gradient-to-r from-green-400 to-emerald-600' : 'bg-gradient-to-r from-indigo-500 to-blue-600'}`} style={{ width: `${weeklyProgress}%` }}><div className="absolute inset-0 bg-white/20 animate-shine" /></div></div></GlassCard>
            <div className="flex p-1 bg-white/40 dark:bg-white/10 rounded-xl backdrop-blur-sm w-fit mx-auto border border-white/20 animate-reveal" style={{ animationDelay: '200ms' }}><button onClick={() => setViewMode('entry')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all duration-300 ${viewMode === 'entry' ? 'bg-black text-white shadow-lg scale-105' : 'text-slate-500 hover:text-slate-700 dark:text-slate-400 hover:bg-black/5'}`}>Manual Entry</button><button onClick={() => setViewMode('calendar')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all duration-300 ${viewMode === 'calendar' ? 'bg-black text-white shadow-lg scale-105' : 'text-slate-500 hover:text-slate-700 dark:text-slate-400 hover:bg-black/5'}`}>History View</button></div>
