                    <GlassButton onClick={handleShare} className="w-full py-4 text-lg animate-reveal" style={{ animationDelay: '500ms' }}><Send size={20} /> Generate & Share Report</GlassButton>
                </div>
            ) : (
                <GlassCard className="p-4 space-y-6 animate-reveal overflow-hidden" style={{ animationDelay: '300ms' }}><div className="flex items-center justify-between px-2"><button onClick={() => setCurrentMonth(new Date(currentMonth.setMonth(currentMonth.getMonth()-1)))} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-white/10 transition-colors"><ChevronLeft size={20} /></button><h3 className="font-bold text-lg">{currentMonth.toLocaleString('default', { month: 'long', year: 'numeric' })}</h3><button onClick={() => setCurrentMonth(new Date(currentMonth.setMonth(currentMonth.getMonth()+1)))} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-white/10 transition-colors"><ChevronRight size={20} /></button></div><div className="grid grid-cols-7 gap-2">{['S', 'M', 'T', 'W', 'T', 'F', 'S'].map(d => ( <div key={d} className="text-center text-[10px] font-bold text-slate-400 uppercase opacity-50">{d}</div> ))}{calendarDays.map((d, i) => { if (!d) return <div key={i} />; const entry = eodHistory.find(e => e.date === d.dateStr); const isToday = d.dateStr === new Date().toISOString().split('T')[0]; const isAchieved = entry && entry.achievement >= entry.dayTarget; return ( <div key={d.dateStr} onClick={() => { setDate(d.dateStr); setViewMode('entry'); }} style={{ animationDelay: `${i * 15}ms` }} className={`aspect-square rounded-xl border flex flex-col items-center justify-center cursor-pointer transition-all duration-300 relative animate-in zoom-in-90 fade-in fill-mode-backwards ${isToday ? 'border-blue-500 ring-2 ring-blue-100 dark:ring-blue-900/30 scale-105 z-10' : 'border-transparent hover:bg-slate-50 dark:hover:bg-white/5 hover:scale-110'} ${entry ? 'bg-white dark:bg-zinc-800 shadow-sm border-gray-100 dark:border-white/5' : 'bg-transparent'}`}> <span className={`text-xs ${isToday ? 'font-black text-blue-600' : 'text-slate-500'}`}>{d.day}</span> {entry && ( <div className={`w-1.5 h-1.5 rounded-full mt-1 ${isAchieved ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]' : 'bg-blue-400'}`} /> )} </div> ); })}</div><div className="space-y-3 pt-4 border-t border-gray-100 dark:border-white/5"><h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest px-1">Weekly History</h4><div className="space-y-3">{eodHistory.filter(e => e.date.startsWith(currentMonth.toISOString().slice(0, 7))).sort((a,b) => b.date.localeCompare(a.date)).map((entry, idx) => ( <div key={entry.date} style={{ animationDelay: `${idx * 100}ms` }} className="flex justify-between items-center p-3 bg-white/40 dark:bg-white/5 rounded-xl border border-white/20 hover:border-blue-400/50 transition-all group animate-in slide-in-from-right-4 fade-in fill-mode-backwards"> <div><p className="text-sm font-bold">{formatToDisplayDate(entry.date)}</p><p className="text-[10px] text-slate-500">Achieved: ₹<CountUp end={entry.achievement} /></p></div><div className="flex items-center gap-4"><div className={`px-2 py-0.5 rounded text-[10px] font-bold ${entry.achievement >= entry.dayTarget ? 'bg-green-100 text-green-600' : 'bg-blue-100 text-blue-600'}`}>{Math.round((entry.achievement / entry.dayTarget) * 100)}%</div><button onClick={(e) => { e.stopPropagation(); handleDelete(entry.date); }} className="text-red-400 hover:text-red-600 p-1 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"><Trash2 size={16} /></button></div></div> ))}</div></div></GlassCard>
            )}
            <Modal isOpen={showSuccess} onClose={() => setShowSuccess(false)} title="Report Generated">
                <div className="text-center space-y-6 pt-4 animate-reveal"><div className="relative w-20 h-20 mx-auto"><div className="absolute inset-0 bg-green-500/20 rounded-full animate-pulse-slow scale-150" /><div className="relative w-20 h-20 bg-green-100 dark:bg-green-900/30 rounded-full flex items-center justify-center text-green-600 shadow-inner"><Check size={40} className="animate-in zoom-in duration-500" strokeWidth={3} /></div></div><div><p className="text-lg font-bold">Entry Saved!</p><p className="text-sm text-slate-500 mt-1">EOD totals for {formatToDisplayDate(date)} have been recorded.</p></div><GlassButton onClick={() => setShowSuccess(false)} variant="secondary" className="w-full border-green-200">Continue</GlassButton></div>
            </Modal>
        </div>
    );
};

export default EOD;
